FILES = {'src/windows_runtime/read_worker.rs': '//! One bounded, read-only provider worker. No mutation is allowed here.\n//! After a timeout, refuse new work until the exact old call completed.\n//! Discard its late reply; resume only with a new request on the same thread.\nuse std::sync::atomic::{AtomicBool, Ordering};\nuse std::sync::mpsc::{self, SyncSender, TryRecvError};\nuse std::sync::{Arc, Mutex};\nuse std::time::{Duration, Instant};\n\nstruct Read<Q, R> {\n    input: Q,\n    result: SyncSender<R>,\n    completed: Arc<AtomicBool>,\n}\n\n#[derive(Default)]\nstruct ReaderState {\n    in_flight: Option<Arc<AtomicBool>>,\n    caller_active: bool,\n    timed_out: bool,\n    disconnected: bool,\n}\n\npub struct BoundedReader<Q, R> {\n    requests: SyncSender<Read<Q, R>>,\n    state: Mutex<ReaderState>,\n}\n\nimpl<Q: Send + \'static, R: Send + \'static> BoundedReader<Q, R> {\n    pub fn start(mut process: impl FnMut(Q) -> R + Send + \'static) -> std::io::Result<Self> {\n        let (requests, queue) = mpsc::sync_channel::<Read<Q, R>>(1);\n        std::thread::Builder::new()\n            .name("g-switcher-uia-reader".into())\n            .spawn(move || {\n                while let Ok(request) = queue.recv() {\n                    let result = process(request.input);\n                    // Completion acknowledges provider quiescence only. It\n                    // never grants writable/security authority to the caller.\n                    request.completed.store(true, Ordering::Release);\n                    let _ = request.result.try_send(result);\n                }\n            })?;\n        Ok(Self { requests, state: Mutex::new(ReaderState::default()) })\n    }\n\n    pub fn request(&self, input: Q, timeout: Duration) -> Option<R> {\n        let deadline = Instant::now().checked_add(timeout)?;\n        let completed = Arc::new(AtomicBool::new(false));\n        let recovered = {\n            let mut state = self.state.try_lock().ok()?;\n            if state.disconnected || state.caller_active {\n                return None;\n            }\n            if state.in_flight.as_ref().is_some_and(|old| !old.load(Ordering::Acquire)) {\n                return None;\n            }\n            let recovered = state.timed_out;\n            state.timed_out = false;\n            state.in_flight = Some(completed.clone());\n            state.caller_active = true;\n            recovered\n        };\n        struct Caller<\'a>(&\'a Mutex<ReaderState>);\n        impl Drop for Caller<\'_> {\n            fn drop(&mut self) {\n                if let Ok(mut state) = self.0.lock() {\n                    state.caller_active = false;\n                }\n            }\n        }\n        let _caller = Caller(&self.state);\n        if recovered { trace_reader("reader-recovered-fresh-request"); }\n        let (result, response) = mpsc::sync_channel(1);\n        if self.requests.try_send(Read { input, result, completed }).is_err() {\n            self.state.lock().ok()?.disconnected = true;\n            trace_reader("reader-disconnected");\n            return None;\n        }\n        loop {\n            pump_sent_messages();\n            if Instant::now() >= deadline {\n                self.state.lock().ok()?.timed_out = true;\n                trace_reader("reader-timeout-awaiting-old-completion");\n                return None;\n            }\n            match response.try_recv() {\n                Ok(value) => return Some(value),\n                Err(TryRecvError::Disconnected) => {\n                    self.state.lock().ok()?.disconnected = true;\n                    trace_reader("reader-disconnected");\n                    return None;\n                }\n                Err(TryRecvError::Empty) => std::thread::sleep(Duration::from_millis(1)),\n            }\n        }\n    }\n}\n\nfn trace_reader(stage: &str) {\n    use std::io::Write;\n    let path = std::env::temp_dir().join("GSwitcher-Word-Runtime.log");\n    let oversized = std::fs::metadata(&path).is_ok_and(|meta| meta.len() > 1_048_576);\n    if let Ok(mut file) = std::fs::OpenOptions::new().create(true).write(true)\n        .append(!oversized).truncate(oversized).open(path) {\n        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap_or_default().as_millis();\n        let _ = writeln!(file, "{now} pid={} stage={stage}", std::process::id());\n    }\n}\n\npub fn pump_sent_messages() {\n    #[cfg(windows)]\n    unsafe {\n        use windows_sys::Win32::UI::WindowsAndMessaging::{PeekMessageW, MSG, PM_NOREMOVE};\n        let mut message: MSG = std::mem::zeroed();\n        // PeekMessage dispatches pending nonqueued sent messages even when no\n        // posted message is removed. Do not Translate/Dispatch posted messages.\n        PeekMessageW(&mut message, std::ptr::null_mut(), 0, 0, PM_NOREMOVE);\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use std::sync::{Arc, Condvar, Mutex};\n    use std::time::{Duration, Instant};\n\n    #[test]\n    fn provider_runs_off_the_requesting_thread() {\n        let caller = std::thread::current().id();\n        let reader = BoundedReader::start(|()| std::thread::current().id()).unwrap();\n        let observed = reader\n            .request((), Duration::from_secs(1))\n            .expect("metadata worker must respond");\n        assert_ne!(observed, caller);\n    }\n\n    #[test]\n    fn stalled_metadata_returns_none_and_never_queues_a_replacement() {\n        let gate = Arc::new((Mutex::new(false), Condvar::new()));\n        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));\n        let worker_gate = gate.clone();\n        let worker_calls = calls.clone();\n        let reader = BoundedReader::start(move |value| {\n            worker_calls.fetch_add(1, Ordering::SeqCst);\n            let (lock, wake) = &*worker_gate;\n            let _guard = wake\n                .wait_while(lock.lock().unwrap(), |ready| !*ready)\n                .unwrap();\n            value\n        })\n        .unwrap();\n        // Baseline synchronous behavior is released eventually, so RED cannot hang.\n        let release = gate.clone();\n        let releaser = std::thread::spawn(move || {\n            std::thread::sleep(Duration::from_millis(250));\n            *release.0.lock().unwrap() = true;\n            release.1.notify_all();\n        });\n        let started = Instant::now();\n        let result = reader.request(42, Duration::from_millis(20));\n        let elapsed = started.elapsed();\n        let second = reader.request(43, Duration::from_millis(20));\n        releaser.join().unwrap();\n        assert_eq!(\n            result, None,\n            "late metadata must not become writable authority"\n        );\n        assert!(\n            elapsed < Duration::from_millis(200),\n            "caller blocked {elapsed:?}"\n        );\n        assert_eq!(second, None, "a timed-out reader remains quarantined");\n        assert_eq!(calls.load(Ordering::SeqCst), 1);\n        let deadline = Instant::now() + Duration::from_secs(1);\n        loop {\n            if let Some(value) = reader.request(44, Duration::from_millis(100)) {\n                assert_eq!(value, 44);\n                break;\n            }\n            assert!(Instant::now() < deadline);\n            std::thread::sleep(Duration::from_millis(1));\n        }\n        assert_eq!(calls.load(Ordering::SeqCst), 2);\n    }\n\n    #[test]\n    fn each_successful_request_reads_fresh_state() {\n        let mut revision = 0;\n        let reader = BoundedReader::start(move |()| {\n            revision += 1;\n            revision\n        })\n        .unwrap();\n        assert_eq!(reader.request((), Duration::from_secs(1)), Some(1));\n        assert_eq!(reader.request((), Duration::from_secs(1)), Some(2));\n    }\n\n    #[test]\n    fn provider_failure_returns_none_without_panicking_the_caller() {\n        let reader = BoundedReader::<(), ()>::start(|()| panic!("provider failed")).unwrap();\n        assert_eq!(reader.request((), Duration::from_secs(1)), None);\n        assert_eq!(reader.request((), Duration::from_secs(1)), None);\n    }\n}\n\n#[cfg(all(test, windows))]\nmod windows_tests {\n    use super::*;\n    use std::ptr::{null, null_mut};\n    use windows_sys::Win32::Foundation::{HWND, LPARAM, LRESULT, WPARAM};\n    use windows_sys::Win32::System::LibraryLoader::GetModuleHandleW;\n    use windows_sys::Win32::UI::WindowsAndMessaging::{\n        CreateWindowExW, DefWindowProcW, DestroyWindow, GetWindowLongPtrW, PeekMessageW,\n        PostMessageW, RegisterClassW, SendMessageTimeoutW, GWLP_USERDATA, HWND_MESSAGE, MSG,\n        PM_REMOVE, SMTO_ABORTIFHUNG, WM_APP, WNDCLASSW,\n    };\n    const QUERY: u32 = WM_APP + 77;\n    const POSTED: u32 = WM_APP + 78;\n    unsafe extern "system" fn window_proc(\n        hwnd: HWND,\n        message: u32,\n        w: WPARAM,\n        l: LPARAM,\n    ) -> LRESULT {\n        if message == QUERY {\n            return 123;\n        }\n        if message == POSTED {\n            // A posted callback must remain queued while the reader waits.\n            return GetWindowLongPtrW(hwnd, GWLP_USERDATA);\n        }\n        DefWindowProcW(hwnd, message, w, l)\n    }\n    #[test]\n    fn sent_message_callbacks_remain_live_but_posted_work_is_not_reentered() {\n        unsafe {\n            let class: Vec<u16> = format!(\n                "GSwitcher.Reader.Test.{}",\n                GetModuleHandleW(null()) as usize\n            )\n            .encode_utf16()\n            .chain(Some(0))\n            .collect();\n            let module = GetModuleHandleW(null());\n            let definition = WNDCLASSW {\n                lpfnWndProc: Some(window_proc),\n                hInstance: module,\n                lpszClassName: class.as_ptr(),\n                ..std::mem::zeroed()\n            };\n            // The same source module can occur in more than one adapter namespace.\n            let _ = RegisterClassW(&definition);\n            let hwnd = CreateWindowExW(\n                0,\n                class.as_ptr(),\n                class.as_ptr(),\n                0,\n                0,\n                0,\n                0,\n                0,\n                HWND_MESSAGE,\n                null_mut(),\n                module,\n                null(),\n            );\n            assert!(!hwnd.is_null());\n            assert_ne!(PostMessageW(hwnd, POSTED, 0, 0), 0);\n            let reader = BoundedReader::start(|handle: isize| {\n                let mut value = 0;\n                let ok = SendMessageTimeoutW(\n                    handle as HWND,\n                    QUERY,\n                    0,\n                    0,\n                    SMTO_ABORTIFHUNG,\n                    400,\n                    &mut value,\n                );\n                (ok != 0, value)\n            })\n            .unwrap();\n            let result = reader.request(hwnd as isize, Duration::from_secs(1));\n            let mut posted: MSG = std::mem::zeroed();\n            let still_queued = PeekMessageW(&mut posted, hwnd, POSTED, POSTED, PM_REMOVE);\n            DestroyWindow(hwnd);\n            assert_eq!(result, Some((true, 123)));\n            assert_ne!(\n                still_queued, 0,\n                "wait must not dispatch posted runtime work"\n            );\n        }\n    }\n}\n\n#[cfg(test)]\nmod concurrency_tests {\n    use super::*;\n    use std::sync::{Arc, Condvar, Mutex};\n    #[test]\n    fn concurrent_requests_cannot_replace_a_stalled_or_quarantined_reader() {\n        let gate = Arc::new((Mutex::new(false), Condvar::new()));\n        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));\n        let worker_gate = gate.clone();\n        let worker_calls = calls.clone();\n        let (started_tx, started_rx) = mpsc::sync_channel(1);\n        let (ended_tx, ended_rx) = mpsc::sync_channel(1);\n        let reader = Arc::new(\n            BoundedReader::start(move |value| {\n                worker_calls.fetch_add(1, Ordering::SeqCst);\n                started_tx.send(()).unwrap();\n                let _guard = worker_gate\n                    .1\n                    .wait_while(worker_gate.0.lock().unwrap(), |ready| !*ready)\n                    .unwrap();\n                ended_tx.send(()).unwrap();\n                value\n            })\n            .unwrap(),\n        );\n        let first_reader = reader.clone();\n        let first = std::thread::spawn(move || first_reader.request(1, Duration::from_millis(80)));\n        started_rx.recv_timeout(Duration::from_secs(1)).unwrap();\n        let other_readers: Vec<_> = (0..16)\n            .map(|_| {\n                let reader = reader.clone();\n                std::thread::spawn(move || reader.request(2, Duration::from_secs(1)))\n            })\n            .collect();\n        for other in other_readers {\n            assert_eq!(other.join().unwrap(), None);\n        }\n        assert_eq!(first.join().unwrap(), None);\n        let after_timeout: Vec<_> = (0..16)\n            .map(|_| {\n                let reader = reader.clone();\n                std::thread::spawn(move || reader.request(3, Duration::from_secs(1)))\n            })\n            .collect();\n        for other in after_timeout {\n            assert_eq!(other.join().unwrap(), None);\n        }\n        *gate.0.lock().unwrap() = true;\n        gate.1.notify_all();\n        ended_rx.recv_timeout(Duration::from_secs(1)).unwrap();\n        let deadline = Instant::now() + Duration::from_secs(1);\n        loop {\n            if let Some(value) = reader.request(4, Duration::from_millis(100)) {\n                assert_eq!(value, 4);\n                break;\n            }\n            assert!(Instant::now() < deadline);\n            std::thread::sleep(Duration::from_millis(1));\n        }\n        assert_eq!(calls.load(Ordering::SeqCst), 2);\n    }\n}\n\n#[cfg(test)]\nmod recovery_regression {\n    use super::*;\n    use std::sync::{Arc, Condvar, Mutex};\n    #[test]\n    fn transient_stall_recovers_same_worker_with_fresh_result_only() {\n        let gate = Arc::new((Mutex::new(false), Condvar::new()));\n        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));\n        let worker_gate = gate.clone();\n        let worker_calls = calls.clone();\n        let (started_tx, started_rx) = mpsc::sync_channel(1);\n        let reader = Arc::new(BoundedReader::start(move |value| {\n            if worker_calls.fetch_add(1, Ordering::SeqCst) == 0 {\n                started_tx.send(std::thread::current().id()).unwrap();\n                let _guard = worker_gate.1.wait_while(worker_gate.0.lock().unwrap(), |ready| !*ready).unwrap();\n            }\n            (value, std::thread::current().id())\n        }).unwrap());\n        let first_reader = reader.clone();\n        let first = std::thread::spawn(move || first_reader.request(42, Duration::from_millis(30)));\n        let worker_id = started_rx.recv_timeout(Duration::from_secs(1)).unwrap();\n        assert_eq!(first.join().unwrap(), None);\n        let contenders: Vec<_> = (0..32).map(|_| {\n            let reader = reader.clone();\n            std::thread::spawn(move || reader.request(77, Duration::from_millis(20)))\n        }).collect();\n        for contender in contenders { assert_eq!(contender.join().unwrap(), None); }\n        assert_eq!(calls.load(Ordering::SeqCst), 1, "no request or replacement while provider is stalled");\n        *gate.0.lock().unwrap() = true;\n        gate.1.notify_all();\n        let deadline = Instant::now() + Duration::from_secs(1);\n        let fresh = loop {\n            if let Some(value) = reader.request(99, Duration::from_millis(100)) { break value; }\n            assert!(Instant::now() < deadline, "transient delay permanently disabled reader");\n            std::thread::sleep(Duration::from_millis(1));\n        };\n        assert_eq!(fresh, (99, worker_id), "never accept old42, and never create a replacement thread");\n        assert_eq!(calls.load(Ordering::SeqCst), 2);\n    }\n}\n', 'src/windows_runtime_v201.rs': '#[path = "windows_runtime/runtime_dispatch.rs"]\nmod runtime_dispatch;\n#[path = "windows_runtime/secure_input.rs"]\nmod secure_input;\n#[path = "windows_runtime/selection.rs"]\nmod selection;\n#[path = "windows_runtime/settings.rs"]\nmod settings;\n#[path = "windows_runtime/sound.rs"]\nmod sound;\n#[path = "windows_runtime/tray_status.rs"]\nmod tray_status;\n#[path = "windows_runtime/ui.rs"]\nmod ui;\n#[path = "windows_runtime/uia_secure.rs"]\nmod uia_secure;\n\nuse std::mem::{size_of, zeroed};\nuse std::ptr::{null, null_mut};\nuse std::sync::atomic::{AtomicIsize, AtomicU32, AtomicU64, AtomicU8, Ordering};\nuse std::sync::{mpsc, OnceLock};\nuse std::thread::{self, JoinHandle};\nuse std::time::Instant;\n\n#[cfg(test)]\nuse std::sync::atomic::AtomicBool;\n\nuse anyhow::{anyhow, Result};\nuse parking_lot::Mutex;\nuse windows_sys::Win32::Foundation::{\n    CloseHandle, GetLastError, ERROR_ALREADY_EXISTS, HINSTANCE, HWND, LPARAM, LRESULT, WPARAM,\n};\nuse windows_sys::Win32::System::LibraryLoader::GetModuleHandleW;\nuse windows_sys::Win32::System::Threading::{\n    CreateMutexW, GetCurrentThreadId, OpenProcess, QueryFullProcessImageNameW, Sleep,\n    PROCESS_QUERY_LIMITED_INFORMATION,\n};\nuse windows_sys::Win32::UI::Input::KeyboardAndMouse::{\n    ActivateKeyboardLayout, GetAsyncKeyState, GetKeyState, GetKeyboardLayout,\n    GetKeyboardLayoutList, LoadKeyboardLayoutW, SendInput, VkKeyScanExW, INPUT, INPUT_0,\n    INPUT_KEYBOARD, KEYBDINPUT, KEYEVENTF_KEYUP, KEYEVENTF_SCANCODE, VK_BACK, VK_CAPITAL,\n    VK_CONTROL, VK_DELETE, VK_DOWN, VK_END, VK_HOME, VK_INSERT, VK_LEFT, VK_MENU, VK_NEXT,\n    VK_OEM_1, VK_OEM_2, VK_OEM_3, VK_OEM_4, VK_OEM_5, VK_OEM_6, VK_OEM_7, VK_OEM_COMMA,\n    VK_OEM_MINUS, VK_OEM_PERIOD, VK_OEM_PLUS, VK_PRIOR, VK_RETURN, VK_RIGHT, VK_SHIFT, VK_SPACE,\n    VK_TAB, VK_UP,\n};\nuse windows_sys::Win32::UI::WindowsAndMessaging::{\n    CallNextHookEx, DispatchMessageW, GetForegroundWindow, GetGUIThreadInfo, GetMessageW,\n    GetWindowThreadProcessId, MessageBoxW, PeekMessageW, PostMessageW, PostThreadMessageW,\n    SetWindowsHookExW, TranslateMessage, UnhookWindowsHookEx, GUITHREADINFO, KBDLLHOOKSTRUCT,\n    LLKHF_INJECTED, MB_ICONERROR, MB_OK, MSG, MSLLHOOKSTRUCT, PM_NOREMOVE, WH_KEYBOARD_LL,\n    WH_MOUSE_LL, WM_APP, WM_INPUTLANGCHANGEREQUEST, WM_KEYDOWN, WM_LBUTTONDOWN, WM_MBUTTONDOWN,\n    WM_MOUSEWHEEL, WM_QUIT, WM_RBUTTONDOWN, WM_SYSKEYDOWN,\n};\n\nuse crate::code_safe::is_code_safe_token;\nuse crate::detector::{\n    correction_at_boundary_with_context, correction_with_context, infer_language,\n    opposite_candidate_is_prefix_for_language, MAX_CONTEXT_WORDS,\n};\nuse crate::layout::opposite_layout_text;\nuse crate::model::Language;\nuse settings::AppMode;\n\nconst MAGIC_EXTRA_INFO: usize = 0x4753_5749_5443_4845;\nconst SINGLE_INSTANCE_NAME: &str = "Local\\\\GSwitcher.SingleInstance.v0.8";\nconst WM_RUNTIME_KEY_EVENT: u32 = WM_APP + 0x60;\nconst WM_RUNTIME_CORRECTION: u32 = WM_APP + 0x61;\nconst WM_RUNTIME_SELECTION: u32 = WM_APP + 0x62;\nconst WM_RUNTIME_INVALIDATE: u32 = WM_APP + 0x63;\n\nconst POLICY_UNKNOWN: u8 = 0;\nconst POLICY_READY: u8 = 1;\nconst POLICY_DENY: u8 = 2;\n\nstatic ENGINE: OnceLock<Mutex<Engine>> = OnceLock::new();\nstatic RUNTIME_WINDOW: AtomicIsize = AtomicIsize::new(0);\nstatic HOOK_FOCUS: AtomicIsize = AtomicIsize::new(0);\nstatic HOOK_POLICY: AtomicU8 = AtomicU8::new(POLICY_UNKNOWN);\nstatic CONTEXT_GENERATION: AtomicU32 = AtomicU32::new(1);\nstatic HOTKEY_SELECTED: AtomicU32 = AtomicU32::new(0);\nstatic HOTKEY_MANUAL: AtomicU32 = AtomicU32::new(0);\nstatic HOTKEY_PREVIOUS: AtomicU32 = AtomicU32::new(0);\nstatic HOTKEY_UNDO: AtomicU32 = AtomicU32::new(0);\nstatic HOTKEY_PAUSE: AtomicU32 = AtomicU32::new(0);\nstatic CALLBACK_COUNT: AtomicU64 = AtomicU64::new(0);\nstatic CALLBACK_MAX_NS: AtomicU64 = AtomicU64::new(0);\nstatic CALLBACK_OVER_10MS: AtomicU64 = AtomicU64::new(0);\nstatic DROPPED_EVENTS: AtomicU64 = AtomicU64::new(0);\n\n#[cfg(test)]\nstatic TEST_ACCEPT_INJECTED_INPUT: AtomicBool = AtomicBool::new(false);\n\n#[derive(Debug, Clone, Copy)]\nstruct FocusTarget {\n    hwnd: HWND,\n    thread_id: u32,\n    process_id: u32,\n    hkl: isize,\n    language: Language,\n}\n\n#[derive(Debug, Clone, Copy, PartialEq, Eq)]\nstruct Stroke {\n    vk: u16,\n    shift: bool,\n}\n\n#[derive(Debug, Clone, Copy)]\nenum Delimiter {\n    VirtualKey(u16),\n    Character(char),\n}\n\nimpl Delimiter {\n    fn text(self) -> String {\n        match self {\n            Self::VirtualKey(VK_SPACE) => " ".to_owned(),\n            Self::VirtualKey(VK_TAB) => "\\t".to_owned(),\n            Self::VirtualKey(VK_RETURN) => "\\r\\n".to_owned(),\n            Self::VirtualKey(_) => String::new(),\n            Self::Character(ch) => ch.to_string(),\n        }\n    }\n}\n\n#[derive(Debug, Clone, Copy, Default)]\nstruct Modifiers {\n    ctrl: bool,\n    shift: bool,\n    alt: bool,\n}\n\n#[derive(Debug, Clone, Copy)]\nstruct HookEvent {\n    vk: u16,\n    modifiers: Modifiers,\n    caps: bool,\n    focus: isize,\n    generation: u32,\n    suppressed: bool,\n}\n\n#[derive(Debug, Clone)]\nstruct PreviousToken {\n    focus: isize,\n    process_id: u32,\n    generation: u32,\n    source_hkl: isize,\n    source_language: Language,\n    text: String,\n    strokes: Vec<Stroke>,\n    delimiter: Delimiter,\n}\n\n#[derive(Debug, Clone)]\nstruct RuntimeUndo {\n    focus: isize,\n    process_id: u32,\n    generation: u32,\n    source_hkl: isize,\n    source_language: Language,\n    target_hkl: isize,\n    original_text: String,\n    corrected_text: String,\n    original_strokes: Vec<Stroke>,\n    corrected_len: usize,\n    delimiter: Option<Delimiter>,\n}\n\n#[derive(Debug, Clone)]\nstruct SelectionUndo {\n    focus: isize,\n    process_id: u32,\n    generation: u32,\n    source_hkl: isize,\n    source_language: Language,\n    target_hkl: isize,\n    corrected: String,\n    original: String,\n}\n\n#[derive(Debug, Clone)]\nstruct PendingCorrection {\n    focus: isize,\n    thread_id: u32,\n    process_id: u32,\n    generation: u32,\n    source_hkl: isize,\n    source_language: Language,\n    target_hkl: isize,\n    original_text: String,\n    corrected: String,\n    replacement_text: String,\n    erase_len: usize,\n    original_strokes: Vec<Stroke>,\n    delimiter: Option<Delimiter>,\n    held_modifiers: Modifiers,\n}\n\n#[derive(Debug, Clone, Copy)]\nstruct PendingSelection {\n    focus: isize,\n    process_id: u32,\n    generation: u32,\n}\n\n#[derive(Debug, Clone, Copy, Default)]\nstruct UiaSecurityCache {\n    generation: u32,\n    process_id: u32,\n    focus: isize,\n    native_hwnd: isize,\n    checked: bool,\n    is_password: Option<bool>,\n    retry_after: Option<Instant>,\n}\n\nimpl UiaSecurityCache {\n    fn reusable_at(&self, now: Instant) -> bool {\n        self.checked\n            && (self.is_password.is_some()\n                || self.retry_after.is_some_and(|deadline| now < deadline))\n    }\n}\n\n#[derive(Default)]\nstruct Engine {\n    candidate: String,\n    strokes: Vec<Stroke>,\n    candidate_focus: isize,\n    previous: Option<PreviousToken>,\n    context_tokens: Vec<String>,\n    undo: Option<RuntimeUndo>,\n    selection_undo: Option<SelectionUndo>,\n    pending_correction: Option<PendingCorrection>,\n    pending_selection: Option<PendingSelection>,\n    process_id: u32,\n    process_name: String,\n    generation: u32,\n    uia_cache: UiaSecurityCache,\n}\n\npub fn run() -> Result<()> {\n    let mutex = SingleInstance::acquire()?;\n    if !mutex.is_primary {\n        return Ok(());\n    }\n\n    settings::set_paused(false);\n    if !settings::first_run_completed() {\n        let Some(preferences) = ui::show_first_run()? else {\n            return Ok(());\n        };\n        let mut runtime = settings::runtime_settings();\n        runtime.sound_enabled = preferences.sound_enabled;\n        runtime.sound_volume = preferences.sound_volume;\n        settings::save_runtime_settings(runtime)?;\n        settings::set_autostart(preferences.autostart)?;\n        settings::mark_first_run_completed()?;\n    }\n\n    unsafe {\n        let mut message: MSG = zeroed();\n        PeekMessageW(&mut message, null_mut(), 0, 0, PM_NOREMOVE);\n    }\n\n    publish_hotkeys(&settings::runtime_settings());\n    selection::configure_runtime_policy(current_generation, settings::paused);\n    let tray = ui::TrayGuard::install()?;\n    ENGINE.get_or_init(|| Mutex::new(Engine::default()));\n    let hook = KeyboardHook::install()?;\n\n    let mut message: MSG = unsafe { zeroed() };\n    loop {\n        let result = unsafe { GetMessageW(&mut message, null_mut(), 0, 0) };\n        if result <= 0 {\n            break;\n        }\n        if handle_runtime_message(&message) {\n            continue;\n        }\n        unsafe {\n            TranslateMessage(&message);\n            DispatchMessageW(&message);\n        }\n    }\n\n    drop(hook);\n    drop(tray);\n    drop(mutex);\n    Ok(())\n}\n\npub fn show_fatal_error(message: &str) {\n    let message = wide(message);\n    let title = wide("G-switcher — ошибка запуска");\n    unsafe {\n        MessageBoxW(\n            null_mut(),\n            message.as_ptr(),\n            title.as_ptr(),\n            MB_OK | MB_ICONERROR,\n        );\n    }\n}\n\npub(crate) fn paused() -> bool {\n    settings::paused()\n}\n\npub(crate) fn toggle_pause() -> bool {\n    let value = settings::toggle_paused();\n    invalidate_context(false);\n    if let Some(engine) = ENGINE.get() {\n        engine.lock().reset_transient();\n    }\n    tray_status::set_paused(value);\n    value\n}\n\npub(crate) fn current_process_name() -> Option<String> {\n    let engine = ENGINE.get()?;\n    let process_name = engine.lock().process_name.clone();\n    (!process_name.is_empty()).then_some(process_name)\n}\n\nfn handle_runtime_message(message: &MSG) -> bool {\n    let Some(engine) = ENGINE.get() else {\n        return false;\n    };\n    match message.message {\n        WM_RUNTIME_KEY_EVENT => {\n            let event = decode_hook_event(message.wParam, message.lParam);\n            engine.lock().on_key_event(event);\n            true\n        }\n        WM_RUNTIME_CORRECTION => {\n            engine.lock().execute_pending_correction();\n            true\n        }\n        WM_RUNTIME_SELECTION => {\n            engine.lock().execute_pending_selection();\n            true\n        }\n        WM_RUNTIME_INVALIDATE => {\n            engine.lock().reset_transient();\n            true\n        }\n        _ => false,\n    }\n}\n\nstruct SingleInstance {\n    handle: *mut core::ffi::c_void,\n    is_primary: bool,\n}\n\nimpl SingleInstance {\n    fn acquire() -> Result<Self> {\n        let name = wide(SINGLE_INSTANCE_NAME);\n        let handle = unsafe { CreateMutexW(null(), 0, name.as_ptr()) };\n        if handle.is_null() {\n            return Err(anyhow!("CreateMutexW failed"));\n        }\n        let is_primary = unsafe { GetLastError() } != ERROR_ALREADY_EXISTS;\n        Ok(Self { handle, is_primary })\n    }\n}\n\nimpl Drop for SingleInstance {\n    fn drop(&mut self) {\n        if !self.handle.is_null() {\n            unsafe { CloseHandle(self.handle) };\n        }\n    }\n}\n\nstruct KeyboardHook {\n    thread_id: u32,\n    join: Option<JoinHandle<()>>,\n    _dispatch: runtime_dispatch::RuntimeDispatchWindow,\n}\n\nimpl KeyboardHook {\n    fn install() -> Result<Self> {\n        publish_hotkeys(&settings::runtime_settings());\n        let dispatch = runtime_dispatch::RuntimeDispatchWindow::install()?;\n\n        let (ready_tx, ready_rx) = mpsc::sync_channel::<std::result::Result<u32, String>>(1);\n        let join = thread::spawn(move || hook_thread_main(ready_tx));\n        let thread_id = ready_rx\n            .recv()\n            .map_err(|_| anyhow!("hook thread exited before initialization"))?\n            .map_err(|message| anyhow!(message))?;\n        Ok(Self {\n            thread_id,\n            join: Some(join),\n            _dispatch: dispatch,\n        })\n    }\n}\n\nimpl Drop for KeyboardHook {\n    fn drop(&mut self) {\n        unsafe {\n            PostThreadMessageW(self.thread_id, WM_QUIT, 0, 0);\n        }\n        if let Some(join) = self.join.take() {\n            let _ = join.join();\n        }\n    }\n}\n\nfn hook_thread_main(ready_tx: mpsc::SyncSender<std::result::Result<u32, String>>) {\n    unsafe {\n        let thread_id = GetCurrentThreadId();\n        let mut message: MSG = zeroed();\n        PeekMessageW(&mut message, null_mut(), 0, 0, PM_NOREMOVE);\n\n        let module = GetModuleHandleW(null()) as HINSTANCE;\n        let keyboard = SetWindowsHookExW(WH_KEYBOARD_LL, Some(keyboard_proc), module, 0);\n        if keyboard.is_null() {\n            let _ = ready_tx.send(Err("SetWindowsHookExW(WH_KEYBOARD_LL) failed".to_owned()));\n            return;\n        }\n        let mouse = SetWindowsHookExW(WH_MOUSE_LL, Some(mouse_proc), module, 0);\n        if mouse.is_null() {\n            UnhookWindowsHookEx(keyboard);\n            let _ = ready_tx.send(Err("SetWindowsHookExW(WH_MOUSE_LL) failed".to_owned()));\n            return;\n        }\n        let _ = ready_tx.send(Ok(thread_id));\n\n        while GetMessageW(&mut message, null_mut(), 0, 0) > 0 {\n            TranslateMessage(&message);\n            DispatchMessageW(&message);\n        }\n        UnhookWindowsHookEx(mouse);\n        UnhookWindowsHookEx(keyboard);\n    }\n}\n\nunsafe extern "system" fn keyboard_proc(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {\n    let started = Instant::now();\n    let result = keyboard_proc_inner(code, wparam, lparam);\n    record_callback_time(started.elapsed().as_nanos().min(u64::MAX as u128) as u64);\n    result\n}\n\nunsafe fn keyboard_proc_inner(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {\n    if code < 0 || (wparam as u32 != WM_KEYDOWN && wparam as u32 != WM_SYSKEYDOWN) {\n        return CallNextHookEx(null_mut(), code, wparam, lparam);\n    }\n    let event = &*(lparam as *const KBDLLHOOKSTRUCT);\n    if should_ignore_hook_event(event) {\n        return CallNextHookEx(null_mut(), code, wparam, lparam);\n    }\n\n    let focus = focused_hwnd_fast() as isize;\n    let previous_focus = HOOK_FOCUS.swap(focus, Ordering::SeqCst);\n    let mut generation = CONTEXT_GENERATION.load(Ordering::SeqCst);\n    if focus == 0 || previous_focus != focus {\n        generation = CONTEXT_GENERATION\n            .fetch_add(1, Ordering::SeqCst)\n            .wrapping_add(1);\n        HOOK_POLICY.store(POLICY_UNKNOWN, Ordering::SeqCst);\n    }\n\n    let modifiers = capture_modifiers();\n    let caps = GetKeyState(VK_CAPITAL as i32) & 1 != 0;\n    if invalidates_context(event.vkCode as u16, modifiers) {\n        generation = CONTEXT_GENERATION\n            .fetch_add(1, Ordering::SeqCst)\n            .wrapping_add(1);\n    }\n\n    let ready = focus != 0\n        && HOOK_POLICY.load(Ordering::SeqCst) == POLICY_READY\n        && HOOK_FOCUS.load(Ordering::SeqCst) == focus;\n    let hotkey = ready && matches_published_hotkey(event.vkCode as u16, modifiers);\n    let packed = encode_hook_event(event.vkCode as u16, modifiers, caps, generation, hotkey);\n    let posted = post_runtime(WM_RUNTIME_KEY_EVENT, packed, focus);\n    if !posted {\n        DROPPED_EVENTS.fetch_add(1, Ordering::Relaxed);\n        invalidate_context(true);\n        return CallNextHookEx(null_mut(), code, wparam, lparam);\n    }\n\n    if hotkey {\n        1\n    } else {\n        CallNextHookEx(null_mut(), code, wparam, lparam)\n    }\n}\n\nunsafe extern "system" fn mouse_proc(code: i32, wparam: WPARAM, lparam: LPARAM) -> LRESULT {\n    let started = Instant::now();\n    if code >= 0\n        && matches!(\n            wparam as u32,\n            WM_LBUTTONDOWN | WM_RBUTTONDOWN | WM_MBUTTONDOWN | WM_MOUSEWHEEL\n        )\n    {\n        let event = &*(lparam as *const MSLLHOOKSTRUCT);\n        if event.dwExtraInfo != MAGIC_EXTRA_INFO {\n            invalidate_context(true);\n            let _ = post_runtime(WM_RUNTIME_INVALIDATE, 0, 0);\n        }\n    }\n    let result = CallNextHookEx(null_mut(), code, wparam, lparam);\n    record_callback_time(started.elapsed().as_nanos().min(u64::MAX as u128) as u64);\n    result\n}\n\nfn should_ignore_hook_event(event: &KBDLLHOOKSTRUCT) -> bool {\n    if event.dwExtraInfo == MAGIC_EXTRA_INFO {\n        return true;\n    }\n    if event.flags & LLKHF_INJECTED == 0 {\n        return false;\n    }\n\n    #[cfg(test)]\n    if TEST_ACCEPT_INJECTED_INPUT.load(Ordering::SeqCst) {\n        return false;\n    }\n\n    true\n}\n\nfn focused_hwnd_fast() -> HWND {\n    unsafe {\n        let foreground = GetForegroundWindow();\n        if foreground.is_null() {\n            return null_mut();\n        }\n        let foreground_thread = GetWindowThreadProcessId(foreground, null_mut());\n        if foreground_thread == 0 {\n            return foreground;\n        }\n        let mut info: GUITHREADINFO = zeroed();\n        info.cbSize = size_of::<GUITHREADINFO>() as u32;\n        if GetGUIThreadInfo(foreground_thread, &mut info) != 0 && !info.hwndFocus.is_null() {\n            info.hwndFocus\n        } else {\n            foreground\n        }\n    }\n}\n\nfn post_runtime(message: u32, wparam: usize, lparam: isize) -> bool {\n    let hwnd = RUNTIME_WINDOW.load(Ordering::SeqCst) as HWND;\n    if hwnd.is_null() {\n        return false;\n    }\n    unsafe { PostMessageW(hwnd, message, wparam, lparam) != 0 }\n}\n\nfn invalidate_context(policy_unknown: bool) {\n    CONTEXT_GENERATION.fetch_add(1, Ordering::SeqCst);\n    if policy_unknown {\n        HOOK_POLICY.store(POLICY_UNKNOWN, Ordering::SeqCst);\n    }\n}\n\nfn record_callback_time(elapsed_ns: u64) {\n    CALLBACK_COUNT.fetch_add(1, Ordering::Relaxed);\n    if elapsed_ns > 10_000_000 {\n        CALLBACK_OVER_10MS.fetch_add(1, Ordering::Relaxed);\n    }\n    let mut current = CALLBACK_MAX_NS.load(Ordering::Relaxed);\n    while elapsed_ns > current {\n        match CALLBACK_MAX_NS.compare_exchange_weak(\n            current,\n            elapsed_ns,\n            Ordering::Relaxed,\n            Ordering::Relaxed,\n        ) {\n            Ok(_) => break,\n            Err(next) => current = next,\n        }\n    }\n}\n\nfn capture_modifiers() -> Modifiers {\n    unsafe {\n        Modifiers {\n            ctrl: GetAsyncKeyState(VK_CONTROL as i32) < 0,\n            shift: GetAsyncKeyState(VK_SHIFT as i32) < 0,\n            alt: GetAsyncKeyState(VK_MENU as i32) < 0,\n        }\n    }\n}\n\nfn invalidates_context(vk: u16, modifiers: Modifiers) -> bool {\n    // Modifier key-down events are part of our hotkey chords. Invalidating the\n    // generation on Ctrl/Shift/Alt itself would erase the candidate/previous\n    // token before the actual hotkey key arrives.\n    if is_modifier_vk(vk) {\n        return false;\n    }\n    matches!(\n        vk,\n        VK_LEFT\n            | VK_RIGHT\n            | VK_UP\n            | VK_DOWN\n            | VK_HOME\n            | VK_END\n            | VK_PRIOR\n            | VK_NEXT\n            | VK_DELETE\n            | VK_INSERT\n    ) || ((modifiers.ctrl || modifiers.alt) && !matches_published_hotkey(vk, modifiers))\n}\n\nfn publish_hotkeys(runtime: &settings::RuntimeSettings) {\n    HOTKEY_SELECTED.store(pack_hotkey(runtime.selected_text_hotkey), Ordering::SeqCst);\n    HOTKEY_MANUAL.store(pack_hotkey(runtime.manual_current_hotkey), Ordering::SeqCst);\n    HOTKEY_PREVIOUS.store(pack_hotkey(runtime.previous_word_hotkey), Ordering::SeqCst);\n    HOTKEY_UNDO.store(pack_hotkey(runtime.undo_hotkey), Ordering::SeqCst);\n    HOTKEY_PAUSE.store(pack_hotkey(runtime.pause_hotkey), Ordering::SeqCst);\n}\n\nfn pack_hotkey(hotkey: settings::Hotkey) -> u32 {\n    u32::from(hotkey.vk)\n        | (u32::from(hotkey.ctrl) << 16)\n        | (u32::from(hotkey.shift) << 17)\n        | (u32::from(hotkey.alt) << 18)\n}\n\nfn pack_event_key(vk: u16, modifiers: Modifiers) -> u32 {\n    u32::from(vk)\n        | (u32::from(modifiers.ctrl) << 16)\n        | (u32::from(modifiers.shift) << 17)\n        | (u32::from(modifiers.alt) << 18)\n}\n\nfn matches_published_hotkey(vk: u16, modifiers: Modifiers) -> bool {\n    let packed = pack_event_key(vk, modifiers);\n    [\n        &HOTKEY_SELECTED,\n        &HOTKEY_MANUAL,\n        &HOTKEY_PREVIOUS,\n        &HOTKEY_UNDO,\n        &HOTKEY_PAUSE,\n    ]\n    .iter()\n    .any(|hotkey| hotkey.load(Ordering::Relaxed) == packed)\n}\n\nfn encode_hook_event(\n    vk: u16,\n    modifiers: Modifiers,\n    caps: bool,\n    generation: u32,\n    suppressed: bool,\n) -> usize {\n    let mut value = pack_event_key(vk, modifiers) as u64;\n    value |= u64::from(caps) << 19;\n    value |= u64::from(suppressed) << 20;\n    value |= u64::from(generation) << 32;\n    value as usize\n}\n\nfn decode_hook_event(wparam: WPARAM, lparam: LPARAM) -> HookEvent {\n    let value = wparam as u64;\n    HookEvent {\n        vk: (value & 0xffff) as u16,\n        modifiers: Modifiers {\n            ctrl: value & (1 << 16) != 0,\n            shift: value & (1 << 17) != 0,\n            alt: value & (1 << 18) != 0,\n        },\n        caps: value & (1 << 19) != 0,\n        focus: lparam,\n        generation: (value >> 32) as u32,\n        suppressed: value & (1 << 20) != 0,\n    }\n}\n\nimpl Engine {\n    fn uia_password_state(&mut self, target: FocusTarget, generation: u32) -> Option<bool> {\n        let cache_matches = self.uia_cache.reusable_at(Instant::now())\n            && self.uia_cache.generation == generation\n            && self.uia_cache.process_id == target.process_id\n            && self.uia_cache.focus == target.hwnd as isize\n            && (self.uia_cache.native_hwnd == 0\n                || self.uia_cache.native_hwnd == target.hwnd as isize);\n        if cache_matches {\n            return self.uia_cache.is_password;\n        }\n\n        let probe = uia_secure::probe_focused(target.process_id);\n        self.uia_cache = UiaSecurityCache {\n            generation,\n            process_id: target.process_id,\n            focus: target.hwnd as isize,\n            native_hwnd: probe.map(|value| value.native_hwnd).unwrap_or_default(),\n            checked: true,\n            is_password: probe.map(|value| value.is_password),\n            // Unknown metadata never grants permission. Retry after a short\n            // cooldown, without polling the provider on every keystroke.\n            retry_after: probe.is_none().then(|| {\n                Instant::now() + std::time::Duration::from_secs(1)\n            }),\n        };\n        self.uia_cache.is_password\n    }\n\n    fn on_key_event(&mut self, event: HookEvent) {\n        let runtime_settings = settings::runtime_settings();\n        publish_hotkeys(&runtime_settings);\n\n        if self.generation != event.generation {\n            self.reset_transient();\n            self.generation = event.generation;\n        }\n\n        let Some(target) = focused_target() else {\n            HOOK_POLICY.store(POLICY_UNKNOWN, Ordering::SeqCst);\n            self.reset_transient();\n            return;\n        };\n        if target.hwnd as isize != event.focus {\n            HOOK_POLICY.store(POLICY_UNKNOWN, Ordering::SeqCst);\n            self.reset_transient();\n            return;\n        }\n\n        self.refresh_process_name(target.process_id);\n        let app_mode = runtime_settings.app_mode(&self.process_name);\n        tray_status::update_context(app_mode, &self.process_name, target.language);\n        if app_mode == AppMode::Disabled {\n            HOOK_POLICY.store(POLICY_DENY, Ordering::SeqCst);\n            self.reset_transient();\n            return;\n        }\n\n        if secure_input::is_secure_input(target.hwnd, &self.process_name) {\n            HOOK_POLICY.store(POLICY_DENY, Ordering::SeqCst);\n            self.reset_transient();\n            return;\n        }\n\n        // Never suppress a hotkey or accumulate an automatic-correction\n        // candidate for a control that has no synchronously verifiable text\n        // adapter. Unsupported modern controls fail open: original input is\n        // left untouched and the application can be placed in Disabled mode.\n        // Key admission only: do not open Word NativeOM/STA on every letter.\n        // UIA/password metadata below and fresh native mutation guards remain\n        // mandatory. Class/process routing never proves a range writable.\n        if !selection::is_word_target(target.hwnd) && !selection::is_standard_edit(target.hwnd) {\n            HOOK_POLICY.store(POLICY_DENY, Ordering::SeqCst);\n            self.reset_transient();\n            return;\n        }\n\n        // UIA is queried only on the runtime worker and only for metadata. A\n        // plain Edit remains protected by its native password/style checks if\n        // UIA is unavailable. RichEdit requires a successful non-password UIA\n        // probe because its verified text adapter is UIA-backed.\n        match self.uia_password_state(target, event.generation) {\n            Some(true) => {\n                HOOK_POLICY.store(POLICY_DENY, Ordering::SeqCst);\n                self.reset_transient();\n                return;\n            }\n            None if !selection::is_plain_edit(target.hwnd) => {\n                HOOK_POLICY.store(POLICY_DENY, Ordering::SeqCst);\n                self.reset_transient();\n                return;\n            }\n            _ => {}\n        }\n        HOOK_FOCUS.store(target.hwnd as isize, Ordering::SeqCst);\n        HOOK_POLICY.store(POLICY_READY, Ordering::SeqCst);\n\n        if event.suppressed\n            && runtime_settings.pause_hotkey.matches(\n                event.vk,\n                event.modifiers.ctrl,\n                event.modifiers.shift,\n                event.modifiers.alt,\n            )\n        {\n            let value = settings::toggle_paused();\n            self.reset_transient();\n            tray_status::set_paused(value);\n            return;\n        }\n\n        if settings::paused() {\n            self.reset_transient();\n            return;\n        }\n\n        if event.suppressed\n            && runtime_settings.selected_text_hotkey.matches(\n                event.vk,\n                event.modifiers.ctrl,\n                event.modifiers.shift,\n                event.modifiers.alt,\n            )\n        {\n            let _ = self.queue_selected_conversion(target, event.generation);\n            return;\n        }\n\n        if event.suppressed\n            && runtime_settings.manual_current_hotkey.matches(\n                event.vk,\n                event.modifiers.ctrl,\n                event.modifiers.shift,\n                event.modifiers.alt,\n            )\n        {\n            let _ = self.try_manual_convert(target, event.modifiers, event.generation);\n            return;\n        }\n\n        if event.suppressed\n            && runtime_settings.previous_word_hotkey.matches(\n                event.vk,\n                event.modifiers.ctrl,\n                event.modifiers.shift,\n                event.modifiers.alt,\n            )\n        {\n            let _ = self.try_convert_previous(target, event.modifiers, event.generation);\n            return;\n        }\n\n        if event.suppressed\n            && runtime_settings.undo_hotkey.matches(\n                event.vk,\n                event.modifiers.ctrl,\n                event.modifiers.shift,\n                event.modifiers.alt,\n            )\n        {\n            let _ = self.try_undo(target, event.modifiers, event.generation);\n            self.reset_candidate();\n            return;\n        }\n\n        if is_modifier_vk(event.vk) {\n            return;\n        }\n        if invalidates_context(event.vk, event.modifiers) {\n            self.reset_transient();\n            return;\n        }\n        if event.modifiers.ctrl || event.modifiers.alt {\n            self.reset_transient();\n            return;\n        }\n\n        let target_id = target.hwnd as isize;\n        if self.candidate_focus != 0 && self.candidate_focus != target_id {\n            self.reset_transient();\n        }\n        if self.candidate_focus == 0 {\n            self.candidate_focus = target_id;\n        }\n        if let Some(previous) = &self.previous {\n            if previous.focus != target_id\n                || previous.process_id != target.process_id\n                || previous.generation != event.generation\n            {\n                self.previous = None;\n            }\n        }\n\n        if self.undo.is_some() || self.selection_undo.is_some() {\n            self.undo = None;\n            self.selection_undo = None;\n        }\n\n        let allow_auto = app_mode == AppMode::Auto;\n        match event.vk {\n            VK_BACK => {\n                self.previous = None;\n                self.candidate.pop();\n                self.strokes.pop();\n                if self.candidate.is_empty() {\n                    self.reset_candidate();\n                }\n            }\n            VK_SPACE => {\n                self.handle_boundary(\n                    target,\n                    Delimiter::VirtualKey(VK_SPACE),\n                    allow_auto,\n                    event.generation,\n                );\n            }\n            VK_RETURN => {\n                self.handle_boundary(\n                    target,\n                    Delimiter::VirtualKey(VK_RETURN),\n                    allow_auto,\n                    event.generation,\n                );\n            }\n            VK_TAB => {\n                self.handle_boundary(\n                    target,\n                    Delimiter::VirtualKey(VK_TAB),\n                    allow_auto,\n                    event.generation,\n                );\n            }\n            VK_OEM_2 => self.handle_punctuation(\n                target,\n                event.vk,\n                allow_auto,\n                event.modifiers.shift,\n                event.caps,\n                event.generation,\n            ),\n            VK_OEM_COMMA | VK_OEM_PERIOD if target.language == Language::English => self\n                .handle_punctuation(\n                    target,\n                    event.vk,\n                    allow_auto,\n                    event.modifiers.shift,\n                    event.caps,\n                    event.generation,\n                ),\n            _ => {\n                self.previous = None;\n                if let Some(ch) =\n                    visible_char(event.vk, target.language, event.modifiers.shift, event.caps)\n                {\n                    self.candidate.push(ch);\n                    self.strokes.push(Stroke {\n                        vk: event.vk,\n                        shift: event.modifiers.shift,\n                    });\n                } else {\n                    self.reset_candidate();\n                }\n            }\n        }\n    }\n\n    fn refresh_process_name(&mut self, process_id: u32) {\n        if self.process_id == process_id {\n            return;\n        }\n        self.reset_transient();\n        self.process_id = process_id;\n        self.process_name = process_name_for_pid(process_id).unwrap_or_default();\n    }\n\n    fn handle_boundary(\n        &mut self,\n        target: FocusTarget,\n        delimiter: Delimiter,\n        allow_auto: bool,\n        generation: u32,\n    ) {\n        if allow_auto && self.try_correct(target, delimiter, true, generation) {\n            self.previous = None;\n        } else {\n            self.remember_previous(target, delimiter, generation);\n            self.remember_context_candidate();\n            self.reset_candidate();\n        }\n    }\n\n    fn handle_punctuation(\n        &mut self,\n        target: FocusTarget,\n        vk: u16,\n        allow_auto: bool,\n        shift: bool,\n        caps: bool,\n        generation: u32,\n    ) {\n        let Some(ch) = visible_char(vk, target.language, shift, caps) else {\n            self.reset_transient();\n            return;\n        };\n        let delimiter = Delimiter::Character(ch);\n\n        if is_code_safe_token(&self.candidate) {\n            self.previous = None;\n            self.candidate.push(ch);\n            self.strokes.push(Stroke { vk, shift });\n            return;\n        }\n\n        if allow_auto && self.try_correct(target, delimiter, false, generation) {\n            self.previous = None;\n            return;\n        }\n\n        let runtime_settings = settings::runtime_settings();\n        let mut prospective = self.candidate.clone();\n        prospective.push(ch);\n        if is_code_safe_token(&prospective)\n            || (punctuation_can_extend_candidate(vk, target.language)\n                && opposite_candidate_is_prefix_for_language(\n                    &prospective,\n                    target.language,\n                    &runtime_settings.user_words,\n                ))\n        {\n            self.previous = None;\n            self.candidate.push(ch);\n            self.strokes.push(Stroke { vk, shift });\n        } else {\n            self.remember_previous(target, delimiter, generation);\n            self.remember_context_candidate();\n            self.reset_candidate();\n        }\n    }\n\n    fn remember_previous(&mut self, target: FocusTarget, delimiter: Delimiter, generation: u32) {\n        if self.candidate.is_empty() || self.strokes.is_empty() {\n            self.previous = None;\n            return;\n        }\n        self.previous = Some(PreviousToken {\n            focus: target.hwnd as isize,\n            process_id: target.process_id,\n            generation,\n            source_hkl: target.hkl,\n            source_language: target.language,\n            text: self.candidate.clone(),\n            strokes: self.strokes.clone(),\n            delimiter,\n        });\n    }\n\n    fn remember_context_candidate(&mut self) {\n        if self.candidate.is_empty()\n            || is_code_safe_token(&self.candidate)\n            || infer_language(&self.candidate).is_none()\n        {\n            return;\n        }\n        self.push_context(self.candidate.clone());\n    }\n\n    fn push_context(&mut self, token: String) {\n        if infer_language(&token).is_none() || is_code_safe_token(&token) {\n            return;\n        }\n        if self.context_tokens.len() >= MAX_CONTEXT_WORDS {\n            self.context_tokens.remove(0);\n        }\n        self.context_tokens.push(token);\n    }\n\n    fn try_correct(\n        &mut self,\n        source: FocusTarget,\n        delimiter: Delimiter,\n        at_boundary: bool,\n        generation: u32,\n    ) -> bool {\n        if self.candidate.is_empty()\n            || self.strokes.is_empty()\n            || self.pending_correction.is_some()\n            || is_code_safe_token(&self.candidate)\n        {\n            return false;\n        }\n\n        let runtime_settings = settings::runtime_settings();\n        if !runtime_settings.auto_correct {\n            return false;\n        }\n        let detection = if at_boundary {\n            correction_at_boundary_with_context(\n                &self.candidate,\n                &runtime_settings.user_words,\n                runtime_settings.sensitivity.confidence_threshold(),\n                &self.context_tokens,\n            )\n        } else {\n            correction_with_context(\n                &self.candidate,\n                &runtime_settings.user_words,\n                runtime_settings.sensitivity.confidence_threshold(),\n                &self.context_tokens,\n            )\n        };\n        let Some(detection) = detection else {\n            return false;\n        };\n        if detection.source != source.language {\n            return false;\n        }\n\n        self.queue_correction_parts(\n            source,\n            detection.target,\n            self.candidate.clone(),\n            detection.corrected,\n            self.candidate.chars().count() + 1,\n            self.strokes.clone(),\n            Some(delimiter),\n            Modifiers::default(),\n            generation,\n        )\n    }\n\n    fn queue_selected_conversion(&mut self, target: FocusTarget, generation: u32) -> bool {\n        if self.pending_selection.is_some() || self.pending_correction.is_some() {\n            return false;\n        }\n        self.reset_candidate();\n        self.previous = None;\n        self.context_tokens.clear();\n        self.undo = None;\n        self.selection_undo = None;\n        self.pending_selection = Some(PendingSelection {\n            focus: target.hwnd as isize,\n            process_id: target.process_id,\n            generation,\n        });\n        if !post_runtime(WM_RUNTIME_SELECTION, 0, 0) {\n            self.pending_selection = None;\n            return false;\n        }\n        true\n    }\n\n    fn execute_pending_selection(&mut self) {\n        let Some(pending) = self.pending_selection.take() else {\n            return;\n        };\n        if settings::paused() || current_generation() != pending.generation {\n            return;\n        }\n        let Some(target) = focused_target() else {\n            return;\n        };\n        if target.hwnd as isize != pending.focus || target.process_id != pending.process_id {\n            return;\n        }\n        self.refresh_process_name(target.process_id);\n        let runtime_settings = settings::runtime_settings();\n        if runtime_settings.app_mode(&self.process_name) == AppMode::Disabled\n            || secure_input::is_secure_input(target.hwnd, &self.process_name)\n            || !selection::is_standard_edit(target.hwnd)\n        {\n            return;\n        }\n        match self.uia_password_state(target, pending.generation) {\n            Some(true) => return,\n            None if !selection::is_plain_edit(target.hwnd) => return,\n            _ => {}\n        }\n\n        let Some(selected) = selection::read_selected_text(target.hwnd) else {\n            return;\n        };\n        let Some(source_language) = infer_language(&selected.text) else {\n            return;\n        };\n        let target_language = opposite_language(source_language);\n        let corrected = opposite_layout_text(&selected.text, source_language);\n        if corrected == selected.text {\n            return;\n        }\n        let Some(target_hkl) = select_layout(target_language) else {\n            return;\n        };\n        if !switch_layout(target.hwnd, target.thread_id, target_hkl) {\n            return;\n        }\n        if current_generation() != pending.generation\n            || focused_target().is_none_or(|now| {\n                now.hwnd as isize != pending.focus || now.process_id != pending.process_id\n            })\n        {\n            let _ = switch_layout(target.hwnd, target.thread_id, target.hkl);\n            return;\n        }\n        if !selection::replace_range_if_matches(\n            target.hwnd,\n            selected.start,\n            selected.end,\n            &selected.text,\n            &corrected,\n        ) {\n            let _ = switch_layout(target.hwnd, target.thread_id, target.hkl);\n            return;\n        }\n\n        self.selection_undo = Some(SelectionUndo {\n            focus: target.hwnd as isize,\n            process_id: target.process_id,\n            generation: pending.generation,\n            source_hkl: target.hkl,\n            source_language: target.language,\n            target_hkl,\n            corrected: corrected.clone(),\n            original: selected.text,\n        });\n        self.undo = None;\n        self.reset_candidate();\n        self.previous = None;\n        self.context_tokens.clear();\n        tray_status::note_correction(target_language);\n        sound::play_correction(&runtime_settings);\n    }\n\n    fn try_manual_convert(\n        &mut self,\n        source: FocusTarget,\n        modifiers: Modifiers,\n        generation: u32,\n    ) -> bool {\n        if self.candidate.is_empty() || self.strokes.is_empty() || self.pending_correction.is_some()\n        {\n            return false;\n        }\n        // The default manual hotkeys use Ctrl+Shift. On Windows installations\n        // where Ctrl+Shift is also configured as an input-language shortcut,\n        // the OS may change the focused thread HKL before F12/F10 reaches us.\n        // The candidate itself still records the alphabet that was typed, so\n        // derive the manual source language from that text instead of trusting\n        // the potentially hotkey-shifted current HKL.\n        let source_language = infer_language(&self.candidate).unwrap_or(source.language);\n        let source_hkl = if source_language == source.language {\n            source.hkl\n        } else {\n            let Some(hkl) = select_layout(source_language) else {\n                return false;\n            };\n            hkl\n        };\n        let source = FocusTarget {\n            hkl: source_hkl,\n            language: source_language,\n            ..source\n        };\n        let target = opposite_language(source_language);\n        let corrected = opposite_layout_text(&self.candidate, source_language);\n        self.previous = None;\n        self.selection_undo = None;\n        self.queue_correction_parts(\n            source,\n            target,\n            self.candidate.clone(),\n            corrected,\n            self.candidate.chars().count(),\n            self.strokes.clone(),\n            None,\n            modifiers,\n            generation,\n        )\n    }\n\n    fn try_convert_previous(\n        &mut self,\n        target: FocusTarget,\n        modifiers: Modifiers,\n        generation: u32,\n    ) -> bool {\n        if self.pending_correction.is_some() || !self.candidate.is_empty() {\n            return false;\n        }\n        let Some(previous) = self.previous.clone() else {\n            return false;\n        };\n        if previous.focus != target.hwnd as isize\n            || previous.process_id != target.process_id\n            || previous.generation != generation\n        {\n            self.previous = None;\n            return false;\n        }\n\n        let previous_text = previous.text.clone();\n        let corrected = opposite_layout_text(&previous.text, previous.source_language);\n        let source = FocusTarget {\n            hkl: previous.source_hkl,\n            language: previous.source_language,\n            ..target\n        };\n        self.selection_undo = None;\n        let queued = self.queue_correction_parts(\n            source,\n            opposite_language(previous.source_language),\n            previous.text.clone(),\n            corrected,\n            previous.text.chars().count() + 1,\n            previous.strokes,\n            Some(previous.delimiter),\n            modifiers,\n            generation,\n        );\n        if queued {\n            self.previous = None;\n            if self.context_tokens.last() == Some(&previous_text) {\n                self.context_tokens.pop();\n            }\n        }\n        queued\n    }\n\n    #[allow(clippy::too_many_arguments)]\n    fn queue_correction_parts(\n        &mut self,\n        source: FocusTarget,\n        target_language: Language,\n        original: String,\n        corrected: String,\n        erase_len: usize,\n        original_strokes: Vec<Stroke>,\n        delimiter: Option<Delimiter>,\n        held_modifiers: Modifiers,\n        generation: u32,\n    ) -> bool {\n        // 2.0.1 fails open for controls without a synchronously verifiable\n        // Edit/RichEdit message adapter. UI Automation support is added as a\n        // separate adapter; raw SendInput mutation is not allowed to guess.\n        // Word routing is cheap; the fresh native operation establishes actual\n        // writability. Queueing must not open an availability-only Word STA.\n        if !selection::is_word_target(source.hwnd) && !selection::is_standard_edit(source.hwnd) {\n            return false;\n        }\n\n        let Some(target_hkl) = select_layout(target_language) else {\n            return false;\n        };\n\n        let mut preflight = Vec::new();\n        append_backspaces(&mut preflight, erase_len);\n        if !append_text_for_layout(&mut preflight, &corrected, target_hkl)\n            || !append_optional_delimiter(&mut preflight, delimiter, target_hkl)\n        {\n            return false;\n        }\n\n        let delimiter_text = delimiter.map(Delimiter::text).unwrap_or_default();\n        let original_text = format!("{original}{delimiter_text}");\n        let replacement_text = format!("{corrected}{delimiter_text}");\n        self.pending_correction = Some(PendingCorrection {\n            focus: source.hwnd as isize,\n            thread_id: source.thread_id,\n            process_id: source.process_id,\n            generation,\n            source_hkl: source.hkl,\n            source_language: source.language,\n            target_hkl,\n            original_text,\n            corrected,\n            replacement_text,\n            erase_len,\n            original_strokes,\n            delimiter,\n            held_modifiers,\n        });\n\n        if !post_runtime(WM_RUNTIME_CORRECTION, 0, 0) {\n            self.pending_correction = None;\n            return false;\n        }\n\n        self.reset_candidate();\n        true\n    }\n\n    fn execute_pending_correction(&mut self) {\n        let Some(mut pending) = self.pending_correction.take() else {\n            return;\n        };\n        if settings::paused() || current_generation() != pending.generation {\n            return;\n        }\n        let hwnd = pending.focus as HWND;\n        let Some(now) = focused_target() else {\n            return;\n        };\n        // Explicit manual actions carry their held modifiers. Allow only those\n        // actions to tolerate HKL drift caused by the hotkey chord itself. Focus,\n        // process, UI thread, generation and exact source suffix are still\n        // revalidated before mutation, so unrelated/stale operations remain\n        // fail-open.\n        let manual_layout_drift = pending.held_modifiers.ctrl\n            || pending.held_modifiers.shift\n            || pending.held_modifiers.alt;\n        let pre_operation_hkl = now.hkl;\n        if now.hwnd as isize != pending.focus\n            || now.process_id != pending.process_id\n            || now.thread_id != pending.thread_id\n            || (!manual_layout_drift && now.hkl != pending.source_hkl)\n        {\n            return;\n        }\n        self.refresh_process_name(now.process_id);\n        if secure_input::is_secure_input(hwnd, &self.process_name) {\n            return;\n        }\n\n        // Cache the adapter decision once. If it is unavailable now, leave the\n        // user\'s text untouched. Do not fall through to the legacy SendInput\n        // mutation path if adapter availability changes during the operation.\n        let verified_adapter = selection::is_word_target(hwnd) || selection::is_standard_edit(hwnd);\n        if !verified_adapter {\n            return;\n        }\n        if verified_adapter {\n            let Some((actual, replacement)) = prepare_edit_suffix(\n                hwnd,\n                &pending.original_text,\n                &pending.replacement_text,\n                pending.generation,\n            ) else {\n                return;\n            };\n            // Record Word\'s actual case for our undo and correction context.\n            // The native adapter still rechecks this exact text before writing.\n            let token_size = pending.corrected.chars().count();\n            pending.corrected = replacement.chars().take(token_size).collect();\n            pending.original_text = actual;\n            pending.replacement_text = replacement;\n            if !switch_layout(hwnd, pending.thread_id, pending.target_hkl) {\n                return;\n            }\n            if current_generation() != pending.generation\n                || !selection::replace_suffix_at_caret(\n                    hwnd,\n                    &pending.original_text,\n                    &pending.replacement_text,\n                )\n            {\n                let _ = switch_layout(hwnd, pending.thread_id, pre_operation_hkl);\n                return;\n            }\n        } else {\n            if !switch_layout(hwnd, pending.thread_id, pending.target_hkl) {\n                return;\n            }\n            let active_modifiers = Modifiers {\n                ctrl: pending.held_modifiers.ctrl && is_control_down(),\n                shift: pending.held_modifiers.shift && is_shift_down(),\n                alt: pending.held_modifiers.alt && is_alt_down(),\n            };\n            let mut inputs = Vec::new();\n            append_modifier_releases(&mut inputs, active_modifiers);\n            append_backspaces(&mut inputs, pending.erase_len);\n            if !append_text_for_layout(&mut inputs, &pending.corrected, pending.target_hkl)\n                || !append_optional_delimiter(&mut inputs, pending.delimiter, pending.target_hkl)\n            {\n                let _ = switch_layout(hwnd, pending.thread_id, pre_operation_hkl);\n                return;\n            }\n            append_modifier_presses(&mut inputs, active_modifiers);\n            if !send_inputs_in_layout(&inputs, pending.target_hkl) {\n                let _ = switch_layout(hwnd, pending.thread_id, pending.source_hkl);\n                self.reset_transient();\n                return;\n            }\n        }\n\n        self.undo = Some(RuntimeUndo {\n            focus: pending.focus,\n            process_id: pending.process_id,\n            generation: pending.generation,\n            source_hkl: pending.source_hkl,\n            source_language: pending.source_language,\n            target_hkl: pending.target_hkl,\n            original_text: pending.original_text,\n            corrected_text: pending.replacement_text,\n            original_strokes: pending.original_strokes,\n            corrected_len: pending.corrected.chars().count(),\n            delimiter: pending.delimiter,\n        });\n        self.selection_undo = None;\n\n        if pending.delimiter.is_some() {\n            self.push_context(pending.corrected.clone());\n        }\n        tray_status::note_correction(opposite_language(pending.source_language));\n        sound::play_correction(&settings::runtime_settings());\n    }\n\n    fn try_undo(&mut self, target: FocusTarget, modifiers: Modifiers, generation: u32) -> bool {\n        if let Some(undo) = self.selection_undo.take() {\n            if undo.focus != target.hwnd as isize\n                || undo.process_id != target.process_id\n                || undo.generation != generation\n                || current_generation() != generation\n                || secure_input::is_secure_input(target.hwnd, &self.process_name)\n                || !selection::is_standard_edit(target.hwnd)\n            {\n                return false;\n            }\n            match self.uia_password_state(target, generation) {\n                Some(true) => return false,\n                None if !selection::is_plain_edit(target.hwnd) => return false,\n                _ => {}\n            }\n            if !switch_layout(target.hwnd, target.thread_id, undo.source_hkl) {\n                return false;\n            }\n            if selection::replace_suffix_at_caret(target.hwnd, &undo.corrected, &undo.original) {\n                self.context_tokens.clear();\n                self.previous = None;\n                tray_status::note_undo(undo.source_language);\n                return true;\n            }\n            let _ = switch_layout(target.hwnd, target.thread_id, undo.target_hkl);\n            return false;\n        }\n\n        let Some(undo) = self.undo.take() else {\n            return false;\n        };\n        if undo.focus != target.hwnd as isize\n            || undo.process_id != target.process_id\n            || undo.generation != generation\n            || current_generation() != generation\n        {\n            return false;\n        }\n        if !switch_layout(target.hwnd, target.thread_id, undo.source_hkl) {\n            return false;\n        }\n\n        // Undo is also fail-open. A stale operation may not switch to raw\n        // SendInput merely because the verified adapter disappeared.\n        let verified_adapter = selection::is_standard_edit(target.hwnd);\n        if !verified_adapter {\n            let _ = switch_layout(target.hwnd, target.thread_id, undo.target_hkl);\n            return false;\n        }\n        if verified_adapter {\n            if selection::replace_suffix_at_caret(\n                target.hwnd,\n                &undo.corrected_text,\n                &undo.original_text,\n            ) {\n                self.candidate_focus = target.hwnd as isize;\n                self.previous = None;\n                self.context_tokens.clear();\n                tray_status::note_undo(undo.source_language);\n                return true;\n            }\n            let _ = switch_layout(target.hwnd, target.thread_id, undo.target_hkl);\n            return false;\n        }\n\n        let mut inputs = Vec::new();\n        append_modifier_releases(&mut inputs, modifiers);\n        append_backspaces(\n            &mut inputs,\n            undo.corrected_len + usize::from(undo.delimiter.is_some()),\n        );\n        for stroke in &undo.original_strokes {\n            append_stroke(&mut inputs, *stroke);\n        }\n        if !append_optional_delimiter(&mut inputs, undo.delimiter, undo.source_hkl) {\n            return false;\n        }\n        append_modifier_presses(&mut inputs, modifiers);\n\n        let result = send_inputs_in_layout(&inputs, undo.source_hkl);\n        if result {\n            self.candidate_focus = target.hwnd as isize;\n            self.previous = None;\n            self.context_tokens.clear();\n            tray_status::note_undo(undo.source_language);\n        }\n        result\n    }\n\n    fn reset_candidate(&mut self) {\n        self.candidate.clear();\n        self.strokes.clear();\n        self.candidate_focus = 0;\n    }\n\n    fn reset_transient(&mut self) {\n        self.reset_candidate();\n        self.previous = None;\n        self.context_tokens.clear();\n        self.undo = None;\n        self.selection_undo = None;\n        self.pending_correction = None;\n        self.pending_selection = None;\n    }\n}\n\nfn current_generation() -> u32 {\n    CONTEXT_GENERATION.load(Ordering::SeqCst)\n}\n\nfn prepare_edit_suffix(\n    hwnd: HWND,\n    expected: &str,\n    replacement: &str,\n    generation: u32,\n) -> Option<(String, String)> {\n    if current_generation() != generation || focused_hwnd_fast() != hwnd {\n        return None;\n    }\n    if selection::is_word_target(hwnd) {\n        // A permanent mismatch (notably Word AutoCorrect\'s first capital) is\n        // not input-delivery lag. One fresh snapshot; never poll Word 50 times.\n        return selection::prepare_word_correction_suffix(hwnd, expected, replacement);\n    }\n    for _ in 0..50 {\n        if current_generation() != generation || focused_hwnd_fast() != hwnd {\n            return None;\n        }\n        if selection::suffix_matches_at_caret(hwnd, expected) {\n            return Some((expected.into(), replacement.into()));\n        }\n        unsafe { Sleep(1) };\n    }\n    None\n}\n\nfn focused_target() -> Option<FocusTarget> {\n    unsafe {\n        let foreground = GetForegroundWindow();\n        if foreground.is_null() {\n            return None;\n        }\n        let foreground_thread = GetWindowThreadProcessId(foreground, null_mut());\n        if foreground_thread == 0 {\n            return None;\n        }\n\n        let mut info: GUITHREADINFO = zeroed();\n        info.cbSize = size_of::<GUITHREADINFO>() as u32;\n        let hwnd =\n            if GetGUIThreadInfo(foreground_thread, &mut info) != 0 && !info.hwndFocus.is_null() {\n                info.hwndFocus\n            } else {\n                foreground\n            };\n        let mut process_id = 0u32;\n        let thread_id = GetWindowThreadProcessId(hwnd, &mut process_id);\n        if thread_id == 0 || process_id == 0 {\n            return None;\n        }\n        let hkl = GetKeyboardLayout(thread_id) as isize;\n        let language = language_from_hkl(hkl)?;\n        Some(FocusTarget {\n            hwnd,\n            thread_id,\n            process_id,\n            hkl,\n            language,\n        })\n    }\n}\n\nfn process_name_for_pid(process_id: u32) -> Option<String> {\n    unsafe {\n        let process = OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, 0, process_id);\n        if process.is_null() {\n            return None;\n        }\n        let mut buffer = vec![0u16; 32_768];\n        let mut length = buffer.len() as u32;\n        let result = QueryFullProcessImageNameW(process, 0, buffer.as_mut_ptr(), &mut length);\n        CloseHandle(process);\n        if result == 0 || length == 0 {\n            return None;\n        }\n        let path = String::from_utf16_lossy(&buffer[..length as usize]);\n        path.rsplit([\'\\\\\', \'/\'])\n            .next()\n            .filter(|name| !name.is_empty())\n            .map(|name| name.to_ascii_lowercase())\n    }\n}\n\nfn language_from_hkl(hkl: isize) -> Option<Language> {\n    let lang_id = hkl as usize & 0xffff;\n    match lang_id & 0x03ff {\n        0x09 => Some(Language::English),\n        0x19 => Some(Language::Russian),\n        _ => None,\n    }\n}\n\nfn opposite_language(language: Language) -> Language {\n    match language {\n        Language::Russian => Language::English,\n        Language::English => Language::Russian,\n    }\n}\n\nfn select_layout(language: Language) -> Option<isize> {\n    unsafe {\n        let count = GetKeyboardLayoutList(0, null_mut());\n        if count > 0 {\n            let mut layouts = vec![null_mut(); count as usize];\n            let actual = GetKeyboardLayoutList(count, layouts.as_mut_ptr());\n            for hkl in layouts.into_iter().take(actual.max(0) as usize) {\n                let value = hkl as isize;\n                if language_from_hkl(value) == Some(language) {\n                    return Some(value);\n                }\n            }\n        }\n\n        let id = match language {\n            Language::English => "00000409",\n            Language::Russian => "00000419",\n        };\n        let id = wide(id);\n        let loaded = LoadKeyboardLayoutW(id.as_ptr(), 0);\n        if loaded.is_null() {\n            None\n        } else {\n            Some(loaded as isize)\n        }\n    }\n}\n\nfn switch_layout(hwnd: HWND, thread_id: u32, hkl: isize) -> bool {\n    unsafe {\n        if GetKeyboardLayout(thread_id) as isize == hkl {\n            return true;\n        }\n        if PostMessageW(hwnd, WM_INPUTLANGCHANGEREQUEST, 0, hkl) == 0 {\n            return false;\n        }\n        for _ in 0..40 {\n            Sleep(5);\n            if GetKeyboardLayout(thread_id) as isize == hkl {\n                return true;\n            }\n        }\n        false\n    }\n}\n\nfn punctuation_can_extend_candidate(vk: u16, source: Language) -> bool {\n    matches!(\n        (source, vk),\n        (Language::English, VK_OEM_COMMA | VK_OEM_PERIOD)\n    )\n}\n\nfn visible_char(vk: u16, language: Language, shifted: bool, caps: bool) -> Option<char> {\n    if (b\'A\' as u16..=b\'Z\' as u16).contains(&vk) {\n        let index = (vk - b\'A\' as u16) as usize;\n        let ch = match language {\n            Language::English => "abcdefghijklmnopqrstuvwxyz".chars().nth(index)?,\n            Language::Russian => "фисвуапршолдьтщзйкыегмцчня".chars().nth(index)?,\n        };\n        return Some(if shifted ^ caps {\n            ch.to_uppercase().next().unwrap_or(ch)\n        } else {\n            ch\n        });\n    }\n\n    if (b\'0\' as u16..=b\'9\' as u16).contains(&vk) {\n        let index = (vk - b\'0\' as u16) as usize;\n        if !shifted {\n            return char::from_digit(index as u32, 10);\n        }\n        let symbols = match language {\n            Language::English => ")!@#$%^&*(",\n            Language::Russian => ")!\\"№;%:?*(",\n        };\n        return symbols.chars().nth(index);\n    }\n\n    match (language, vk, shifted) {\n        (_, VK_OEM_MINUS, false) => Some(\'-\'),\n        (_, VK_OEM_MINUS, true) => Some(\'_\'),\n        (_, VK_OEM_PLUS, false) => Some(\'=\'),\n        (_, VK_OEM_PLUS, true) => Some(\'+\'),\n        (Language::English, VK_OEM_5, false) => Some(\'\\\\\'),\n        (Language::English, VK_OEM_5, true) => Some(\'|\'),\n        (Language::Russian, VK_OEM_5, false) => Some(\'\\\\\'),\n        (Language::Russian, VK_OEM_5, true) => Some(\'/\'),\n        (Language::English, VK_OEM_3, false) => Some(\'`\'),\n        (Language::English, VK_OEM_3, true) => Some(\'~\'),\n        (Language::English, VK_OEM_4, false) => Some(\'[\'),\n        (Language::English, VK_OEM_4, true) => Some(\'{\'),\n        (Language::English, VK_OEM_6, false) => Some(\']\'),\n        (Language::English, VK_OEM_6, true) => Some(\'}\'),\n        (Language::English, VK_OEM_1, false) => Some(\';\'),\n        (Language::English, VK_OEM_1, true) => Some(\':\'),\n        (Language::English, VK_OEM_7, false) => Some(\'\\\'\'),\n        (Language::English, VK_OEM_7, true) => Some(\'"\'),\n        (Language::English, VK_OEM_COMMA, false) => Some(\',\'),\n        (Language::English, VK_OEM_COMMA, true) => Some(\'<\'),\n        (Language::English, VK_OEM_PERIOD, false) => Some(\'.\'),\n        (Language::English, VK_OEM_PERIOD, true) => Some(\'>\'),\n        (Language::English, VK_OEM_2, false) => Some(\'/\'),\n        (Language::English, VK_OEM_2, true) => Some(\'?\'),\n        (Language::Russian, VK_OEM_3, false) => Some(\'ё\'),\n        (Language::Russian, VK_OEM_3, true) => Some(\'Ё\'),\n        (Language::Russian, VK_OEM_4, false) => Some(\'х\'),\n        (Language::Russian, VK_OEM_4, true) => Some(\'Х\'),\n        (Language::Russian, VK_OEM_6, false) => Some(\'ъ\'),\n        (Language::Russian, VK_OEM_6, true) => Some(\'Ъ\'),\n        (Language::Russian, VK_OEM_1, false) => Some(\'ж\'),\n        (Language::Russian, VK_OEM_1, true) => Some(\'Ж\'),\n        (Language::Russian, VK_OEM_7, false) => Some(\'э\'),\n        (Language::Russian, VK_OEM_7, true) => Some(\'Э\'),\n        (Language::Russian, VK_OEM_COMMA, false) => Some(\'б\'),\n        (Language::Russian, VK_OEM_COMMA, true) => Some(\'Б\'),\n        (Language::Russian, VK_OEM_PERIOD, false) => Some(\'ю\'),\n        (Language::Russian, VK_OEM_PERIOD, true) => Some(\'Ю\'),\n        (Language::Russian, VK_OEM_2, false) => Some(\'.\'),\n        (Language::Russian, VK_OEM_2, true) => Some(\',\'),\n        _ => None,\n    }\n}\n\nfn is_modifier_vk(vk: u16) -> bool {\n    matches!(\n        vk,\n        0x10 | 0x11 | 0x12 | 0x14 | 0xA0 | 0xA1 | 0xA2 | 0xA3 | 0xA4 | 0xA5\n    )\n}\n\nfn is_shift_down() -> bool {\n    unsafe { GetAsyncKeyState(VK_SHIFT as i32) < 0 }\n}\n\nfn is_control_down() -> bool {\n    unsafe { GetAsyncKeyState(VK_CONTROL as i32) < 0 }\n}\n\nfn is_alt_down() -> bool {\n    unsafe { GetAsyncKeyState(VK_MENU as i32) < 0 }\n}\n\nfn append_modifier_releases(inputs: &mut Vec<INPUT>, modifiers: Modifiers) {\n    if modifiers.ctrl {\n        inputs.push(key_input(VK_CONTROL, KEYEVENTF_KEYUP));\n    }\n    if modifiers.shift {\n        inputs.push(key_input(VK_SHIFT, KEYEVENTF_KEYUP));\n    }\n    if modifiers.alt {\n        inputs.push(key_input(VK_MENU, KEYEVENTF_KEYUP));\n    }\n}\n\nfn append_modifier_presses(inputs: &mut Vec<INPUT>, modifiers: Modifiers) {\n    if modifiers.alt {\n        inputs.push(key_input(VK_MENU, 0));\n    }\n    if modifiers.shift {\n        inputs.push(key_input(VK_SHIFT, 0));\n    }\n    if modifiers.ctrl {\n        inputs.push(key_input(VK_CONTROL, 0));\n    }\n}\n\nfn append_backspaces(inputs: &mut Vec<INPUT>, count: usize) {\n    for _ in 0..count {\n        append_stroke(\n            inputs,\n            Stroke {\n                vk: VK_BACK,\n                shift: false,\n            },\n        );\n    }\n}\n\nfn append_text_for_layout(inputs: &mut Vec<INPUT>, text: &str, hkl: isize) -> bool {\n    for ch in text.chars() {\n        let encoded = unsafe { VkKeyScanExW(ch as u16, hkl as *mut core::ffi::c_void) };\n        if encoded == -1 {\n            return false;\n        }\n        let encoded = encoded as u16;\n        let vk = encoded & 0xff;\n        let modifiers = (encoded >> 8) & 0xff;\n        if modifiers & !1 != 0 {\n            return false;\n        }\n        append_stroke(\n            inputs,\n            Stroke {\n                vk,\n                shift: modifiers & 1 != 0,\n            },\n        );\n    }\n    true\n}\n\nfn append_optional_delimiter(\n    inputs: &mut Vec<INPUT>,\n    delimiter: Option<Delimiter>,\n    hkl: isize,\n) -> bool {\n    delimiter\n        .map(|delimiter| append_delimiter(inputs, delimiter, hkl))\n        .unwrap_or(true)\n}\n\nfn append_delimiter(inputs: &mut Vec<INPUT>, delimiter: Delimiter, hkl: isize) -> bool {\n    match delimiter {\n        Delimiter::VirtualKey(vk) => {\n            append_stroke(inputs, Stroke { vk, shift: false });\n            true\n        }\n        Delimiter::Character(ch) => {\n            let encoded = unsafe { VkKeyScanExW(ch as u16, hkl as *mut core::ffi::c_void) };\n            if encoded == -1 {\n                return false;\n            }\n            let vk = (encoded as u16) & 0xff;\n            let shift = ((encoded as u16) >> 8) & 1 != 0;\n            append_stroke(inputs, Stroke { vk, shift });\n            true\n        }\n    }\n}\n\nfn append_stroke(inputs: &mut Vec<INPUT>, stroke: Stroke) {\n    if stroke.shift {\n        inputs.push(key_input(VK_SHIFT, 0));\n    }\n\n    if let Some(scan) = physical_oem_scan_code(stroke.vk) {\n        inputs.push(scan_input(scan, 0));\n        inputs.push(scan_input(scan, KEYEVENTF_KEYUP));\n    } else {\n        inputs.push(key_input(stroke.vk, 0));\n        inputs.push(key_input(stroke.vk, KEYEVENTF_KEYUP));\n    }\n\n    if stroke.shift {\n        inputs.push(key_input(VK_SHIFT, KEYEVENTF_KEYUP));\n    }\n}\n\nfn physical_oem_scan_code(vk: u16) -> Option<u16> {\n    match vk {\n        VK_OEM_4 => Some(0x1A),\n        VK_OEM_6 => Some(0x1B),\n        VK_OEM_1 => Some(0x27),\n        VK_OEM_7 => Some(0x28),\n        VK_OEM_3 => Some(0x29),\n        VK_OEM_COMMA => Some(0x33),\n        VK_OEM_PERIOD => Some(0x34),\n        VK_OEM_2 => Some(0x35),\n        _ => None,\n    }\n}\n\nfn key_input(vk: u16, flags: u32) -> INPUT {\n    INPUT {\n        r#type: INPUT_KEYBOARD,\n        Anonymous: INPUT_0 {\n            ki: KEYBDINPUT {\n                wVk: vk,\n                wScan: 0,\n                dwFlags: flags,\n                time: 0,\n                dwExtraInfo: MAGIC_EXTRA_INFO,\n            },\n        },\n    }\n}\n\nfn scan_input(scan: u16, flags: u32) -> INPUT {\n    INPUT {\n        r#type: INPUT_KEYBOARD,\n        Anonymous: INPUT_0 {\n            ki: KEYBDINPUT {\n                wVk: 0,\n                wScan: scan,\n                dwFlags: flags | KEYEVENTF_SCANCODE,\n                time: 0,\n                dwExtraInfo: MAGIC_EXTRA_INFO,\n            },\n        },\n    }\n}\n\nfn send_inputs_in_layout(inputs: &[INPUT], hkl: isize) -> bool {\n    unsafe {\n        if ActivateKeyboardLayout(hkl as *mut core::ffi::c_void, 0).is_null() {\n            return false;\n        }\n    }\n    send_inputs(inputs)\n}\n\nconst SEND_INPUT_STALL_RETRY_LIMIT: usize = 32;\n\nfn send_inputs(inputs: &[INPUT]) -> bool {\n    deliver_inputs_with_retry(inputs.len(), |offset, remaining| unsafe {\n        SendInput(\n            remaining as u32,\n            inputs[offset..].as_ptr(),\n            size_of::<INPUT>() as i32,\n        ) as usize\n    })\n}\n\nfn deliver_inputs_with_retry(total: usize, mut send: impl FnMut(usize, usize) -> usize) -> bool {\n    if total == 0 {\n        return true;\n    }\n\n    let mut offset = 0usize;\n    let mut stalled = 0usize;\n    while offset < total {\n        let remaining = total - offset;\n        let sent = send(offset, remaining).min(remaining);\n        if sent == 0 {\n            if offset == 0 {\n                return false;\n            }\n            stalled += 1;\n            if stalled >= SEND_INPUT_STALL_RETRY_LIMIT {\n                return false;\n            }\n            unsafe { Sleep(1) };\n            continue;\n        }\n\n        offset += sent;\n        stalled = 0;\n    }\n    true\n}\n\nfn wide(value: &str) -> Vec<u16> {\n    value.encode_utf16().chain(std::iter::once(0)).collect()\n}\n\n#[cfg(test)]\n#[path = "windows_runtime/cross_process_e2e.rs"]\nmod cross_process_e2e;\n#[cfg(test)]\n#[path = "windows_runtime/e2e_tests.rs"]\nmod e2e_tests;\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n\n    #[test]\n    fn recognizes_ru_and_en_hkl_language_ids() {\n        assert_eq!(language_from_hkl(0x0000_0409), Some(Language::English));\n        assert_eq!(language_from_hkl(0x0000_0809), Some(Language::English));\n        assert_eq!(language_from_hkl(0x0000_0419), Some(Language::Russian));\n        assert_eq!(language_from_hkl(0x0000_0407), None);\n    }\n\n    #[test]\n    fn input_struct_matches_win64_abi_on_64_bit_windows() {\n        #[cfg(target_pointer_width = "64")]\n        assert_eq!(size_of::<INPUT>(), 40);\n    }\n\n    #[test]\n    fn hook_event_roundtrip_preserves_generation_and_decision() {\n        let modifiers = Modifiers {\n            ctrl: true,\n            shift: false,\n            alt: true,\n        };\n        let packed = encode_hook_event(b\'Q\' as u16, modifiers, true, 0x1234_5678, true);\n        let event = decode_hook_event(packed, 42);\n        assert_eq!(event.vk, b\'Q\' as u16);\n        assert!(event.modifiers.ctrl);\n        assert!(!event.modifiers.shift);\n        assert!(event.modifiers.alt);\n        assert!(event.caps);\n        assert!(event.suppressed);\n        assert_eq!(event.focus, 42);\n        assert_eq!(event.generation, 0x1234_5678);\n    }\n\n    #[test]\n    fn navigation_invalidates_context() {\n        assert!(invalidates_context(VK_LEFT, Modifiers::default()));\n        assert!(invalidates_context(VK_HOME, Modifiers::default()));\n        assert!(!invalidates_context(b\'A\' as u16, Modifiers::default()));\n    }\n\n    #[test]\n    fn code_safe_characters_are_kept_in_one_runtime_candidate() {\n        let mut candidate = String::new();\n        for ch in "user_ghbdtn".chars() {\n            candidate.push(ch);\n        }\n        assert!(is_code_safe_token(&candidate));\n        assert!(is_code_safe_token("HOST-ghbdtn-01"));\n        assert!(is_code_safe_token("user@ghbdtn.test"));\n        assert!(is_code_safe_token("C:\\\\ghbdtn\\\\file"));\n        assert!(is_code_safe_token("--ghbdtn"));\n        assert!(!is_code_safe_token("ghbdtn"));\n    }\n\n    #[test]\n    fn visible_char_includes_technical_sequence_keys() {\n        assert_eq!(\n            visible_char(b\'1\' as u16, Language::English, false, false),\n            Some(\'1\')\n        );\n        assert_eq!(\n            visible_char(b\'2\' as u16, Language::English, true, false),\n            Some(\'@\')\n        );\n        assert_eq!(\n            visible_char(VK_OEM_MINUS, Language::English, true, false),\n            Some(\'_\')\n        );\n        assert_eq!(\n            visible_char(VK_OEM_5, Language::English, false, false),\n            Some(\'\\\\\')\n        );\n        assert_eq!(\n            visible_char(VK_OEM_1, Language::English, true, false),\n            Some(\':\')\n        );\n    }\n\n    #[test]\n    fn partial_sendinput_delivery_resumes_from_unsent_tail() {\n        let mut calls = Vec::new();\n        let mut attempt = 0usize;\n        let delivered = deliver_inputs_with_retry(10, |offset, remaining| {\n            calls.push((offset, remaining));\n            attempt += 1;\n            match attempt {\n                1 => 4,\n                2 => 0,\n                _ => remaining,\n            }\n        });\n        assert!(delivered);\n        assert_eq!(calls, vec![(0, 10), (4, 6), (4, 6)]);\n    }\n\n    #[test]\n    fn zero_progress_sendinput_fails_without_deleting_any_tail() {\n        let mut calls = 0usize;\n        let delivered = deliver_inputs_with_retry(10, |offset, remaining| {\n            calls += 1;\n            assert_eq!((offset, remaining), (0, 10));\n            0\n        });\n        assert!(!delivered);\n        assert_eq!(calls, 1);\n    }\n}\n\n#[cfg(test)]\nmod uia_cache_recovery_tests {\n    use super::UiaSecurityCache;\n    use std::time::{Duration, Instant};\n\n    #[test]\n    fn unknown_security_cache_expires_without_becoming_writable() {\n        let now = Instant::now();\n        let cache = UiaSecurityCache {\n            checked: true,\n            is_password: None,\n            retry_after: Some(now + Duration::from_secs(1)),\n            ..Default::default()\n        };\n        assert!(cache.reusable_at(now));\n        assert!(!cache.reusable_at(now + Duration::from_secs(1)));\n        assert!(!cache.reusable_at(now + Duration::from_secs(2)));\n        assert_eq!(cache.is_password, None);\n    }\n\n    #[test]\n    fn known_security_cache_and_unchecked_state_keep_their_policy() {\n        let now = Instant::now();\n        for is_password in [Some(true), Some(false)] {\n            let cache = UiaSecurityCache {\n                checked: true,\n                is_password,\n                ..Default::default()\n            };\n            assert!(cache.reusable_at(now + Duration::from_secs(60)));\n            assert_eq!(cache.is_password, is_password);\n        }\n        assert!(!UiaSecurityCache::default().reusable_at(now));\n    }\n}\n', 'docs/work-status/reader-recovery-2026-10-08.json': '{\n  "schema": "reader-recovery-report/v1",\n  "source_base": "cb1dd4cb1b099e56fb759a19b3a1e2a1b6bc58f0",\n  "reported_symptom": "Initially corrected words then stopped in Word; installed runtime cause not independently measured",\n  "confirmed_source_failure_paths": [\n    "One provider deadline permanently disables reader even after provider completes",\n    "Unknown UIA security cache never expires for unchanged focus and generation"\n  ],\n  "behavior": [\n    "Refuse while exact provider call unfinished; never create replacement thread",\n    "Discard late result; after completion permit fresh request on same worker",\n    "Retry unknown security result after one-second cooldown; unknown never grants permission",\n    "Preserve existing focus, protected-field, evolving-text, one-Undo and uncertain-mutation checks"\n  ],\n  "tests": [\n    "Exact delivered reader plus recovery regression must fail with permanent-disable assertion before applying fix",\n    "Same-thread recovery and stalled-concurrency regression",\n    "Actual runtime negative-cache cooldown and known-security policy tests in WindowsCI"\n  ],\n  "installed_word_acceptance": "pending",\n  "hard_native_com_timeout": false,\n  "public_promotion_authorized": false,\n  "scheduler_paused": true\n}\n'}
RED_SOURCE = '//! One bounded, read-only provider worker. No mutation is allowed here.\n//! A timeout quarantines this worker for the process lifetime; never create\n//! replacement workers or accept a late result as fresh security authority.\nuse std::sync::atomic::{AtomicU8, Ordering};\nuse std::sync::mpsc::{self, SyncSender, TryRecvError};\nuse std::time::{Duration, Instant};\n\nstruct Read<Q, R> {\n    input: Q,\n    result: SyncSender<R>,\n}\n\npub struct BoundedReader<Q, R> {\n    requests: SyncSender<Read<Q, R>>,\n    state: AtomicU8,\n}\nconst READY: u8 = 0;\nconst BUSY: u8 = 1;\nconst QUARANTINED: u8 = 2;\n\nimpl<Q: Send + \'static, R: Send + \'static> BoundedReader<Q, R> {\n    pub fn start(mut process: impl FnMut(Q) -> R + Send + \'static) -> std::io::Result<Self> {\n        let (requests, queue) = mpsc::sync_channel::<Read<Q, R>>(1);\n        // This worker must not own windows or expose COM interfaces to callers.\n        // The provider creates its MTA interfaces on this thread only.\n        std::thread::Builder::new()\n            .name("g-switcher-uia-reader".into())\n            .spawn(move || {\n                while let Ok(request) = queue.recv() {\n                    let result = process(request.input);\n                    let _ = request.result.try_send(result);\n                }\n            })?;\n        Ok(Self {\n            requests,\n            state: AtomicU8::new(READY),\n        })\n    }\n\n    pub fn request(&self, input: Q, timeout: Duration) -> Option<R> {\n        let deadline = Instant::now().checked_add(timeout)?;\n        // Admission and quarantine are one atomic state transition. A caller\n        // cannot observe Ready early and acquire admission after quarantine.\n        if self\n            .state\n            .compare_exchange(READY, BUSY, Ordering::AcqRel, Ordering::Acquire)\n            .is_err()\n        {\n            return None;\n        }\n        struct Busy<\'a>(&\'a AtomicU8);\n        impl Drop for Busy<\'_> {\n            fn drop(&mut self) {\n                // Late completion/drop must never clear a timeout quarantine.\n                let _ = self\n                    .0\n                    .compare_exchange(BUSY, READY, Ordering::AcqRel, Ordering::Acquire);\n            }\n        }\n        let _busy = Busy(&self.state);\n        let (result, response) = mpsc::sync_channel(1);\n        if self.requests.try_send(Read { input, result }).is_err() {\n            self.state.store(QUARANTINED, Ordering::Release);\n            return None;\n        }\n        loop {\n            // Process only incoming SendMessage calls. Never dispatch posted\n            // runtime work while Engine or native mutation serialization is held.\n            pump_sent_messages();\n            if Instant::now() >= deadline {\n                self.state.store(QUARANTINED, Ordering::Release);\n                return None;\n            }\n            match response.try_recv() {\n                Ok(value) => return Some(value),\n                Err(TryRecvError::Disconnected) => {\n                    self.state.store(QUARANTINED, Ordering::Release);\n                    return None;\n                }\n                Err(TryRecvError::Empty) => std::thread::sleep(Duration::from_millis(1)),\n            }\n        }\n    }\n}\n\npub fn pump_sent_messages() {\n    #[cfg(windows)]\n    unsafe {\n        use windows_sys::Win32::UI::WindowsAndMessaging::{PeekMessageW, MSG, PM_NOREMOVE};\n        let mut message: MSG = std::mem::zeroed();\n        // PeekMessage dispatches pending nonqueued sent messages even when no\n        // posted message is removed. Do not Translate/Dispatch posted messages.\n        PeekMessageW(&mut message, std::ptr::null_mut(), 0, 0, PM_NOREMOVE);\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use std::sync::{Arc, Condvar, Mutex};\n    use std::time::{Duration, Instant};\n\n    #[test]\n    fn provider_runs_off_the_requesting_thread() {\n        let caller = std::thread::current().id();\n        let reader = BoundedReader::start(|()| std::thread::current().id()).unwrap();\n        let observed = reader\n            .request((), Duration::from_secs(1))\n            .expect("metadata worker must respond");\n        assert_ne!(observed, caller);\n    }\n\n    #[test]\n    fn stalled_metadata_returns_none_and_never_queues_a_replacement() {\n        let gate = Arc::new((Mutex::new(false), Condvar::new()));\n        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));\n        let worker_gate = gate.clone();\n        let worker_calls = calls.clone();\n        let reader = BoundedReader::start(move |value| {\n            worker_calls.fetch_add(1, Ordering::SeqCst);\n            let (lock, wake) = &*worker_gate;\n            let _guard = wake\n                .wait_while(lock.lock().unwrap(), |ready| !*ready)\n                .unwrap();\n            value\n        })\n        .unwrap();\n        // Baseline synchronous behavior is released eventually, so RED cannot hang.\n        let release = gate.clone();\n        let releaser = std::thread::spawn(move || {\n            std::thread::sleep(Duration::from_millis(250));\n            *release.0.lock().unwrap() = true;\n            release.1.notify_all();\n        });\n        let started = Instant::now();\n        let result = reader.request(42, Duration::from_millis(20));\n        let elapsed = started.elapsed();\n        let second = reader.request(43, Duration::from_millis(20));\n        releaser.join().unwrap();\n        assert_eq!(\n            result, None,\n            "late metadata must not become writable authority"\n        );\n        assert!(\n            elapsed < Duration::from_millis(200),\n            "caller blocked {elapsed:?}"\n        );\n        assert_eq!(second, None, "a timed-out reader remains quarantined");\n        assert_eq!(calls.load(Ordering::SeqCst), 1);\n        assert_eq!(reader.request(44, Duration::from_secs(1)), None);\n    }\n\n    #[test]\n    fn each_successful_request_reads_fresh_state() {\n        let mut revision = 0;\n        let reader = BoundedReader::start(move |()| {\n            revision += 1;\n            revision\n        })\n        .unwrap();\n        assert_eq!(reader.request((), Duration::from_secs(1)), Some(1));\n        assert_eq!(reader.request((), Duration::from_secs(1)), Some(2));\n    }\n\n    #[test]\n    fn provider_failure_returns_none_without_panicking_the_caller() {\n        let reader = BoundedReader::<(), ()>::start(|()| panic!("provider failed")).unwrap();\n        assert_eq!(reader.request((), Duration::from_secs(1)), None);\n        assert_eq!(reader.request((), Duration::from_secs(1)), None);\n    }\n}\n\n#[cfg(all(test, windows))]\nmod windows_tests {\n    use super::*;\n    use std::ptr::{null, null_mut};\n    use windows_sys::Win32::Foundation::{HWND, LPARAM, LRESULT, WPARAM};\n    use windows_sys::Win32::System::LibraryLoader::GetModuleHandleW;\n    use windows_sys::Win32::UI::WindowsAndMessaging::{\n        CreateWindowExW, DefWindowProcW, DestroyWindow, GetWindowLongPtrW, PeekMessageW,\n        PostMessageW, RegisterClassW, SendMessageTimeoutW, GWLP_USERDATA, HWND_MESSAGE, MSG,\n        PM_REMOVE, SMTO_ABORTIFHUNG, WM_APP, WNDCLASSW,\n    };\n    const QUERY: u32 = WM_APP + 77;\n    const POSTED: u32 = WM_APP + 78;\n    unsafe extern "system" fn window_proc(\n        hwnd: HWND,\n        message: u32,\n        w: WPARAM,\n        l: LPARAM,\n    ) -> LRESULT {\n        if message == QUERY {\n            return 123;\n        }\n        if message == POSTED {\n            // A posted callback must remain queued while the reader waits.\n            return GetWindowLongPtrW(hwnd, GWLP_USERDATA);\n        }\n        DefWindowProcW(hwnd, message, w, l)\n    }\n    #[test]\n    fn sent_message_callbacks_remain_live_but_posted_work_is_not_reentered() {\n        unsafe {\n            let class: Vec<u16> = format!(\n                "GSwitcher.Reader.Test.{}",\n                GetModuleHandleW(null()) as usize\n            )\n            .encode_utf16()\n            .chain(Some(0))\n            .collect();\n            let module = GetModuleHandleW(null());\n            let definition = WNDCLASSW {\n                lpfnWndProc: Some(window_proc),\n                hInstance: module,\n                lpszClassName: class.as_ptr(),\n                ..std::mem::zeroed()\n            };\n            // The same source module can occur in more than one adapter namespace.\n            let _ = RegisterClassW(&definition);\n            let hwnd = CreateWindowExW(\n                0,\n                class.as_ptr(),\n                class.as_ptr(),\n                0,\n                0,\n                0,\n                0,\n                0,\n                HWND_MESSAGE,\n                null_mut(),\n                module,\n                null(),\n            );\n            assert!(!hwnd.is_null());\n            assert_ne!(PostMessageW(hwnd, POSTED, 0, 0), 0);\n            let reader = BoundedReader::start(|handle: isize| {\n                let mut value = 0;\n                let ok = SendMessageTimeoutW(\n                    handle as HWND,\n                    QUERY,\n                    0,\n                    0,\n                    SMTO_ABORTIFHUNG,\n                    400,\n                    &mut value,\n                );\n                (ok != 0, value)\n            })\n            .unwrap();\n            let result = reader.request(hwnd as isize, Duration::from_secs(1));\n            let mut posted: MSG = std::mem::zeroed();\n            let still_queued = PeekMessageW(&mut posted, hwnd, POSTED, POSTED, PM_REMOVE);\n            DestroyWindow(hwnd);\n            assert_eq!(result, Some((true, 123)));\n            assert_ne!(\n                still_queued, 0,\n                "wait must not dispatch posted runtime work"\n            );\n        }\n    }\n}\n\n#[cfg(test)]\nmod concurrency_tests {\n    use super::*;\n    use std::sync::{Arc, Condvar, Mutex};\n    #[test]\n    fn concurrent_requests_cannot_replace_a_stalled_or_quarantined_reader() {\n        let gate = Arc::new((Mutex::new(false), Condvar::new()));\n        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));\n        let worker_gate = gate.clone();\n        let worker_calls = calls.clone();\n        let (started_tx, started_rx) = mpsc::sync_channel(1);\n        let (ended_tx, ended_rx) = mpsc::sync_channel(1);\n        let reader = Arc::new(\n            BoundedReader::start(move |value| {\n                worker_calls.fetch_add(1, Ordering::SeqCst);\n                started_tx.send(()).unwrap();\n                let _guard = worker_gate\n                    .1\n                    .wait_while(worker_gate.0.lock().unwrap(), |ready| !*ready)\n                    .unwrap();\n                ended_tx.send(()).unwrap();\n                value\n            })\n            .unwrap(),\n        );\n        let first_reader = reader.clone();\n        let first = std::thread::spawn(move || first_reader.request(1, Duration::from_millis(80)));\n        started_rx.recv_timeout(Duration::from_secs(1)).unwrap();\n        let other_readers: Vec<_> = (0..16)\n            .map(|_| {\n                let reader = reader.clone();\n                std::thread::spawn(move || reader.request(2, Duration::from_secs(1)))\n            })\n            .collect();\n        for other in other_readers {\n            assert_eq!(other.join().unwrap(), None);\n        }\n        assert_eq!(first.join().unwrap(), None);\n        let after_timeout: Vec<_> = (0..16)\n            .map(|_| {\n                let reader = reader.clone();\n                std::thread::spawn(move || reader.request(3, Duration::from_secs(1)))\n            })\n            .collect();\n        for other in after_timeout {\n            assert_eq!(other.join().unwrap(), None);\n        }\n        *gate.0.lock().unwrap() = true;\n        gate.1.notify_all();\n        ended_rx.recv_timeout(Duration::from_secs(1)).unwrap();\n        assert_eq!(reader.request(4, Duration::from_secs(1)), None);\n        assert_eq!(calls.load(Ordering::SeqCst), 1);\n    }\n}\n#[cfg(test)]\nmod recovery_regression {\n    use super::*;\n    use std::sync::{Arc, Condvar, Mutex};\n    #[test]\n    fn transient_stall_recovers_same_worker_with_fresh_result_only() {\n        let gate = Arc::new((Mutex::new(false), Condvar::new()));\n        let calls = Arc::new(std::sync::atomic::AtomicUsize::new(0));\n        let worker_gate = gate.clone();\n        let worker_calls = calls.clone();\n        let (started_tx, started_rx) = mpsc::sync_channel(1);\n        let reader = Arc::new(BoundedReader::start(move |value| {\n            if worker_calls.fetch_add(1, Ordering::SeqCst) == 0 {\n                started_tx.send(std::thread::current().id()).unwrap();\n                let _guard = worker_gate.1.wait_while(worker_gate.0.lock().unwrap(), |ready| !*ready).unwrap();\n            }\n            (value, std::thread::current().id())\n        }).unwrap());\n        let first_reader = reader.clone();\n        let first = std::thread::spawn(move || first_reader.request(42, Duration::from_millis(30)));\n        let worker_id = started_rx.recv_timeout(Duration::from_secs(1)).unwrap();\n        assert_eq!(first.join().unwrap(), None);\n        let contenders: Vec<_> = (0..32).map(|_| {\n            let reader = reader.clone();\n            std::thread::spawn(move || reader.request(77, Duration::from_millis(20)))\n        }).collect();\n        for contender in contenders { assert_eq!(contender.join().unwrap(), None); }\n        assert_eq!(calls.load(Ordering::SeqCst), 1, "no request or replacement while provider is stalled");\n        *gate.0.lock().unwrap() = true;\n        gate.1.notify_all();\n        let deadline = Instant::now() + Duration::from_secs(1);\n        let fresh = loop {\n            if let Some(value) = reader.request(99, Duration::from_millis(100)) { break value; }\n            assert!(Instant::now() < deadline, "transient delay permanently disabled reader");\n            std::thread::sleep(Duration::from_millis(1));\n        };\n        assert_eq!(fresh, (99, worker_id), "never accept old42, and never create a replacement thread");\n        assert_eq!(calls.load(Ordering::SeqCst), 2);\n    }\n}\n'
from pathlib import Path
